function createDestinationMetricDraft(
  destination?: MarketingCampaignDestinationItem
): CampaignDestinationMetricDraft {
  const manualMetrics = destination?.manual_metrics ?? {};
  return {
    impressions: String(manualMetrics.impressions ?? destination?.metricas?.views ?? ""),
    clicks: String(manualMetrics.link_clicks ?? destination?.metricas?.clicks ?? ""),
    engagement: String(manualMetrics.engagement ?? destination?.metricas?.engagement ?? ""),
    leads: String(manualMetrics.leads ?? destination?.metricas?.leads ?? ""),
    spend: String(manualMetrics.spend ?? ""),
    traffic_type: String(manualMetrics.traffic_type ?? "organic"),
    period_start: String(manualMetrics.period_start ?? ""),
    period_end: String(manualMetrics.period_end ?? ""),
    notes: String(manualMetrics.notes ?? ""),
  };
}
