function createCapabilityOverrideDraft(
  client?: SubscriptionItem | null,
): CapabilityOverrideDraft {
  const overrides = client?.plan_capability_overrides;
  const managedMarketing = client?.managed_marketing;
  return {
    modulos_agregados: overrides?.modulos_agregados ?? [],
    modulos_bloqueados: overrides?.modulos_bloqueados ?? [],
    funciones_agregadas: overrides?.funciones_agregadas ?? [],
    funciones_bloqueadas: overrides?.funciones_bloqueadas ?? [],
    nota: overrides?.nota ?? "",
    actualizado_en: overrides?.actualizado_en ?? null,
    actualizado_por: overrides?.actualizado_por ?? null,
    managed_marketing_enabled: Boolean(managedMarketing?.enabled),
    managed_marketing_scope: managedMarketing?.scope ?? "",
    managed_marketing_responsable: managedMarketing?.responsable ?? "",
    managed_marketing_nota: managedMarketing?.nota ?? "",
    managed_marketing_actualizado_en: managedMarketing?.actualizado_en ?? null,
    managed_marketing_actualizado_por: managedMarketing?.actualizado_por ?? null,
  };
}

