function VendeCommercialRecommendation({
  client,
  plans,
  moduleDefinitions,
  featureDefinitions,
  compact = false,
  onPrepareUpgrade,
}: {
  client: SubscriptionItem;
  plans: PlanItem[];
  moduleDefinitions: PlanDefinitionItem[];
  featureDefinitions: PlanDefinitionItem[];
  compact?: boolean;
  onPrepareUpgrade?: (targetPlan: PlanItem | null, reason: string) => void;
}) {
  if (!isVendeFacilPlan(client.plan)) return null;

  const nextPlan = nextVendePlanForClient(client, plans);
  const delta = planDelta(client, nextPlan);
  const signals = vendeCommercialSignals(client);
  const capabilityDelta = [
    ...delta.modules.map((key) => ({
      key: `module-${key}`,
      label: definitionLabel(key, moduleDefinitions),
    })),
    ...delta.features.map((key) => ({
      key: `feature-${key}`,
      label: definitionLabel(key, featureDefinitions),
    })),
  ].slice(0, compact ? 3 : 6);
  const currentLimit = metricNumber(
    client.solution_usage?.limits?.productos ??
      client.plan.solution_profile?.commercial_limits.productos ??
      client.limits.espacios
  );
  const nextLimit = metricNumber(
    nextPlan?.solution_profile?.commercial_limits.productos ?? nextPlan?.max_espacios
  );
  const currentChannels = metricNumber(
    client.solution_usage?.limits?.canales ?? client.plan.solution_profile?.commercial_limits.canales
  );
  const nextChannels = metricNumber(nextPlan?.solution_profile?.commercial_limits.canales);
  const currentWarehouses = metricNumber(
    client.solution_usage?.limits?.bodegas ?? client.plan.solution_profile?.commercial_limits.bodegas
  );
  const nextWarehouses = metricNumber(nextPlan?.solution_profile?.commercial_limits.bodegas);
  const monthlyDelta = nextPlan
    ? Number(nextPlan.precio_mensual || 0) - Number(client.plan.precio_mensual || 0)
    : 0;
  const headline = nextPlan ? `Subir a ${nextPlan.nombre}` : "Revisar plan a medida";
  const reason = signals.length
    ? signals.join(" | ")
    : nextPlan
      ? "Cliente listo para mayor capacidad o canales."
      : "Cliente en el plan superior del catalogo.";
  const actionLabel = nextPlan ? "Preparar upgrade" : "Preparar a medida";
  const gainedCapacity = [
    nextLimit > currentLimit
      ? `${formatNumber(nextLimit - currentLimit)} productos adicionales`
      : "",
    nextChannels > currentChannels
      ? `${formatNumber(nextChannels - currentChannels)} canales adicionales`
      : "",
    nextWarehouses > currentWarehouses
      ? `${formatNumber(nextWarehouses - currentWarehouses)} bodegas adicionales`
      : "",
  ].filter(Boolean);

  return (
    <div
      className={`mt-3 rounded-2xl border border-emerald-500/15 bg-emerald-500/[0.06] ${
        compact ? "max-w-[320px] p-3" : "p-4"
      }`}
    >
      <div className="flex flex-wrap items-start justify-between gap-2">
        <div>
          <p className="text-[10px] font-semibold uppercase tracking-[0.16em] text-emerald-200/80">
            Siguiente venta
          </p>
          <p className="mt-1 text-sm font-semibold text-white">{headline}</p>
        </div>
        {nextPlan && monthlyDelta > 0 ? (
          <span className="rounded-full border border-emerald-500/20 bg-emerald-500/10 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-[0.12em] text-emerald-100">
            +{formatCurrency(monthlyDelta)}/mes
          </span>
        ) : (
          <span className="rounded-full border border-cyan-500/20 bg-cyan-500/10 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-[0.12em] text-cyan-100">
            A medida
          </span>
        )}
      </div>
      <p className="mt-2 text-[11px] leading-5 text-zinc-400">{reason}</p>
      <div className={`mt-3 grid gap-2 ${compact ? "grid-cols-1" : "md:grid-cols-2"}`}>
        <div className="rounded-xl border border-white/8 bg-black/20 p-2">
          <p className="text-[10px] uppercase tracking-[0.14em] text-zinc-500">Plan actual</p>
          <p className="mt-1 font-semibold text-white">{client.plan.nombre}</p>
          <p className="mt-0.5 text-[11px] text-zinc-500">
            {formatCurrency(client.plan.precio_mensual)}/mes
          </p>
        </div>
        <div className="rounded-xl border border-emerald-500/15 bg-emerald-500/10 p-2">
          <p className="text-[10px] uppercase tracking-[0.14em] text-emerald-200/80">
            Recomendado
          </p>
          <p className="mt-1 font-semibold text-white">{nextPlan?.nombre ?? "Plan a medida"}</p>
          <p className="mt-0.5 text-[11px] text-emerald-100/80">
            {nextPlan ? `${formatCurrency(nextPlan.precio_mensual)}/mes` : "Cotizacion comercial"}
          </p>
        </div>
      </div>
      {nextPlan && nextLimit > currentLimit ? (
        <div className="mt-3 grid grid-cols-2 gap-2 text-xs">
          <div className="rounded-xl border border-white/8 bg-black/20 p-2">
            <p className="text-[10px] uppercase tracking-[0.14em] text-zinc-500">Actual</p>
            <p className="mt-1 font-semibold text-white">{formatNumber(currentLimit)} productos</p>
          </div>
          <div className="rounded-xl border border-emerald-500/15 bg-emerald-500/10 p-2">
            <p className="text-[10px] uppercase tracking-[0.14em] text-emerald-200/80">
              Siguiente
            </p>
            <p className="mt-1 font-semibold text-white">{formatNumber(nextLimit)} productos</p>
          </div>
        </div>
      ) : null}
      {capabilityDelta.length ? (
        <div className="mt-3 flex flex-wrap gap-1.5">
          {capabilityDelta.map((item) => (
            <span
              key={item.key}
              className="rounded-full border border-cyan-500/15 bg-cyan-500/10 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-[0.1em] text-cyan-100"
            >
              {item.label}
            </span>
          ))}
        </div>
      ) : null}
      {gainedCapacity.length ? (
        <div className="mt-3 rounded-xl border border-cyan-500/15 bg-cyan-500/10 p-2">
          <p className="text-[10px] uppercase tracking-[0.14em] text-cyan-100/80">
            Capacidad ganada
          </p>
          <p className="mt-1 text-[11px] leading-5 text-cyan-50">
            {gainedCapacity.join(" | ")}
          </p>
        </div>
      ) : null}
      {onPrepareUpgrade ? (
        <button
          type="button"
          onClick={() => onPrepareUpgrade(nextPlan, reason)}
          className="mt-3 w-full rounded-2xl border border-emerald-400/25 bg-emerald-400/15 px-3 py-2 text-xs font-semibold uppercase tracking-[0.14em] text-emerald-50 transition hover:border-emerald-300/45 hover:bg-emerald-400/20"
        >
          {actionLabel}
        </button>
      ) : null}
    </div>
  );
}

function VendeOperationalPlanNotice({
  client,
  plans,
  moduleDefinitions,
  featureDefinitions,
  moduleKey,
  moduleEnabled,
  limit,
  title,
  description,
  onEditPlan,
  onPrepareUpgrade,
}: {
  client: SubscriptionItem;
  plans: PlanItem[];
  moduleDefinitions: PlanDefinitionItem[];
  featureDefinitions: PlanDefinitionItem[];
  moduleKey: string;
  moduleEnabled: boolean;
  limit?: VendeFacilLimitState | null;
  title: string;
  description: string;
  onEditPlan: () => void;
  onPrepareUpgrade?: (targetPlan: PlanItem | null, reason: string) => void;
}) {
  const limitStatus = limit?.status ?? "OK";
  const limitNeedsPlanAction = ["NEAR_LIMIT", "FULL", "EXCEEDED"].includes(limitStatus);
  if (moduleEnabled && !limitNeedsPlanAction) return null;

  const moduleName = definitionLabel(moduleKey, moduleDefinitions);
  const isBlocked = !moduleEnabled || limitStatus === "EXCEEDED" || limitStatus === "FULL";
  const toneClasses = isBlocked
    ? "border-amber-500/20 bg-amber-500/10 text-amber-100"
    : "border-cyan-500/20 bg-cyan-500/10 text-cyan-100";
  const message = !moduleEnabled
    ? `El plan ${client.plan.nombre} no incluye ${moduleName}. Puedes revisar un upgrade o habilitar un override comercial controlado.`
    : `${limit?.label ?? "Capacidad"} esta ${limitStatus === "NEAR_LIMIT" ? "cerca del limite" : "en el limite"}: ${formatNumber(
        limit?.used ?? 0
      )}/${formatNumber(limit?.limit ?? 0)} usado.`;

  return (
    <div className={`mt-4 rounded-2xl border p-4 ${toneClasses}`}>
      <div className="flex flex-col gap-3 lg:flex-row lg:items-start lg:justify-between">
        <div>
          <p className="text-[10px] font-semibold uppercase tracking-[0.16em] opacity-80">
            Plan y operacion
          </p>
          <h4 className="mt-1 text-base font-semibold text-white">{title}</h4>
          <p className="mt-2 max-w-3xl text-sm leading-6 text-zinc-300">{description}</p>
          <p className="mt-2 max-w-3xl text-sm leading-6 text-zinc-200">{message}</p>
        </div>
        <button
          type="button"
          onClick={onEditPlan}
          className="shrink-0 rounded-2xl border border-white/10 bg-white/10 px-4 py-2 text-sm font-semibold text-white transition hover:border-white/20 hover:bg-white/15"
        >
          Revisar plan
        </button>
      </div>
      <VendeCommercialRecommendation
        client={client}
        plans={plans}
        moduleDefinitions={moduleDefinitions}
        featureDefinitions={featureDefinitions}
        compact
        onPrepareUpgrade={onPrepareUpgrade}
      />
    </div>
  );
}

function VendePlanChangePreview({
  client,
  targetPlan,
  moduleDefinitions,
  featureDefinitions,
}: {
  client?: SubscriptionItem | null;
  targetPlan?: PlanItem | null;
  moduleDefinitions: PlanDefinitionItem[];
  featureDefinitions: PlanDefinitionItem[];
}) {
  if (!client || !targetPlan) return null;
  if (!isVendeFacilPlan(client.plan) || !isVendeFacilPlan(targetPlan)) return null;
  if (client.plan.id === targetPlan.id) return null;

  const delta = planDelta(client, targetPlan);
  const unlocked = [
    ...delta.modules.map((key) => ({
      key: `module-${key}`,
      label: definitionLabel(key, moduleDefinitions),
    })),
    ...delta.features.map((key) => ({
      key: `feature-${key}`,
      label: definitionLabel(key, featureDefinitions),
    })),
  ];
  const currentProducts = metricNumber(
    client.solution_usage?.limits?.productos ??
      client.plan.solution_profile?.commercial_limits.productos ??
      client.limits.espacios
  );
  const targetProducts = metricNumber(
    targetPlan.solution_profile?.commercial_limits.productos ?? targetPlan.max_espacios
  );
  const currentChannels = metricNumber(
    client.solution_usage?.limits?.canales ?? client.plan.solution_profile?.commercial_limits.canales
  );
  const targetChannels = metricNumber(targetPlan.solution_profile?.commercial_limits.canales);
  const currentMonthly = Number(client.plan.precio_mensual || 0);
  const targetMonthly = Number(targetPlan.precio_mensual || 0);
  const monthlyDelta = targetMonthly - currentMonthly;

  return (
    <section className="rounded-2xl border border-emerald-500/15 bg-emerald-500/[0.06] p-4">
      <div className="flex flex-col gap-3 lg:flex-row lg:items-start lg:justify-between">
        <div>
          <p className="text-[11px] uppercase tracking-[0.2em] text-emerald-200/80">
            Upgrade preparado
          </p>
          <h4 className="mt-1 text-base font-semibold text-white">
            {client.plan.nombre}
            {" -> "}
            {targetPlan.nombre}
          </h4>
          <p className="mt-2 max-w-3xl text-sm leading-6 text-zinc-400">
            Revisa el cambio antes de guardar. Al confirmar, BetterP actualiza el plan,
            conserva auditoria y programa la sincronizacion operativa de Vende Facil.
          </p>
        </div>
        <span className="rounded-full border border-emerald-500/20 bg-emerald-500/10 px-3 py-1.5 text-xs font-semibold uppercase tracking-[0.14em] text-emerald-100">
          {monthlyDelta >= 0 ? "+" : ""}
          {formatCurrency(monthlyDelta)}/mes
        </span>
      </div>
      <div className="mt-4 grid gap-3 md:grid-cols-3">
        <div className="rounded-xl border border-white/8 bg-black/20 p-3">
          <p className="text-[10px] uppercase tracking-[0.14em] text-zinc-500">Productos</p>
          <p className="mt-1 text-sm font-semibold text-white">
            {formatNumber(currentProducts)}
            {" -> "}
            {formatNumber(targetProducts)}
          </p>
        </div>
        <div className="rounded-xl border border-white/8 bg-black/20 p-3">
          <p className="text-[10px] uppercase tracking-[0.14em] text-zinc-500">Canales</p>
          <p className="mt-1 text-sm font-semibold text-white">
            {formatNumber(currentChannels)}
            {" -> "}
            {formatNumber(targetChannels)}
          </p>
        </div>
        <div className="rounded-xl border border-white/8 bg-black/20 p-3">
          <p className="text-[10px] uppercase tracking-[0.14em] text-zinc-500">MRR</p>
          <p className="mt-1 text-sm font-semibold text-white">
            {formatCurrency(currentMonthly)}
            {" -> "}
            {formatCurrency(targetMonthly)}
          </p>
        </div>
      </div>
      {unlocked.length ? (
        <div className="mt-3 flex flex-wrap gap-1.5">
          {unlocked.slice(0, 8).map((item) => (
            <span
              key={item.key}
              className="rounded-full border border-cyan-500/15 bg-cyan-500/10 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-[0.1em] text-cyan-100"
            >
              {item.label}
            </span>
          ))}
        </div>
      ) : null}
    </section>
  );
}

function VendePlanCommercialMatrix({
  plans,
  clients,
  moduleDefinitions,
  featureDefinitions,
}: {
  plans: PlanItem[];
  clients: SubscriptionItem[];
  moduleDefinitions: PlanDefinitionItem[];
  featureDefinitions: PlanDefinitionItem[];
}) {
  const vendePlans = sortedVendePlans(plans);
  if (!vendePlans.length) return null;
  const clientStats = new Map<number, { total: number; active: number; attention: number }>();
  for (const client of clients) {
    const current = clientStats.get(client.plan.id) ?? { total: 0, active: 0, attention: 0 };
    current.total += 1;
    if (["ACTIVA", "TRIAL", "PAST_DUE"].includes(client.estatus)) current.active += 1;
    if (customerHealthStatus(client).level !== "OK") current.attention += 1;
    clientStats.set(client.plan.id, current);
  }

  const rows = [
    { key: "vende_facil.productos", type: "module", fallback: "Catalogo de productos" },
    { key: "vende_facil.inventario", type: "module", fallback: "Inventario y stock" },
    { key: "vende_facil.conectores", type: "module", fallback: "Conectores y canales" },
    { key: "vende_facil.ordenes", type: "module", fallback: "Ordenes y ventas" },
    { key: "vende_facil.facturacion", type: "module", fallback: "Facturacion" },
    { key: "vende_marketplaces_mx", type: "feature", fallback: "Marketplaces Mexico" },
    { key: "vende_shopify_woocommerce", type: "feature", fallback: "Shopify y WooCommerce" },
    { key: "vende_ai_enrichment", type: "feature", fallback: "IA de calidad" },
    { key: "vende_bulk_sync", type: "feature", fallback: "Sincronizacion masiva" },
    { key: "vende_third_party_api", type: "feature", fallback: "API de terceros" },
  ] as const;

  return (
    <section className="rounded-[28px] border border-cyan-500/15 bg-cyan-500/[0.05] p-5">
      <div className="flex flex-col gap-3 lg:flex-row lg:items-end lg:justify-between">
        <div>
          <p className="text-[11px] uppercase tracking-[0.22em] text-cyan-200/80">
            Vende Facil | Matriz comercial
          </p>
          <h3 className="mt-2 text-lg font-semibold text-white">
            Compara capacidad, precio y funciones antes de vender o subir un plan.
          </h3>
          <p className="mt-2 max-w-3xl text-sm leading-6 text-zinc-400">
            Esta lectura ayuda a soporte y ventas a entender que desbloquea cada segmento sin
            revisar el detalle tecnico del catalogo.
          </p>
        </div>
        <span className="rounded-full border border-cyan-500/20 bg-cyan-500/10 px-3 py-1 text-[11px] font-semibold uppercase tracking-[0.16em] text-cyan-100">
          {formatNumber(vendePlans.length)} plan(es)
        </span>
      </div>

      <div className="mt-5 overflow-x-auto">
        <table className="min-w-[980px] w-full text-left text-sm">
          <thead>
            <tr className="border-b border-white/8 text-[10px] uppercase tracking-[0.18em] text-zinc-500">
              <th className="px-3 py-3 font-medium">Capacidad</th>
              {vendePlans.map((plan) => (
                <th key={plan.id} className="px-3 py-3 font-medium">
                  <div className="space-y-1">
                    <p className="text-xs font-semibold normal-case tracking-normal text-white">
                      {plan.nombre}
                    </p>
                    <p className="text-[10px] text-cyan-200/80">
                      {formatCurrency(plan.precio_mensual)}/mes
                    </p>
                  </div>
                </th>
              ))}
            </tr>
          </thead>
          <tbody className="divide-y divide-white/8">
            <tr>
              <td className="px-3 py-3 text-xs font-semibold text-zinc-300">Limites</td>
              {vendePlans.map((plan) => {
                const limits = plan.solution_profile?.commercial_limits;
                return (
                  <td key={`limits-${plan.id}`} className="px-3 py-3 text-xs leading-5 text-zinc-400">
                    <p>{formatNumber(limits?.productos ?? plan.max_espacios)} productos</p>
                    <p>{formatNumber(limits?.canales ?? 0)} canales</p>
                    <p>{formatNumber(limits?.bodegas ?? plan.max_entidades)} bodegas</p>
                  </td>
                );
              })}
            </tr>
            <tr>
              <td className="px-3 py-3 text-xs font-semibold text-zinc-300">Clientes</td>
              {vendePlans.map((plan) => {
                const stats = clientStats.get(plan.id) ?? { total: 0, active: 0, attention: 0 };
                return (
                  <td key={`clients-${plan.id}`} className="px-3 py-3 text-xs leading-5 text-zinc-400">
                    <p>{formatNumber(stats.total)} total</p>
                    <p>{formatNumber(stats.active)} activos/trial</p>
                    <p className={stats.attention > 0 ? "text-amber-200" : "text-zinc-600"}>
                      {formatNumber(stats.attention)} en atencion
                    </p>
                  </td>
                );
              })}
            </tr>
            {rows.map((row) => (
              <tr key={row.key}>
                <td className="px-3 py-3 text-xs font-semibold text-zinc-300">
                  {(() => {
                    const label =
                      row.type === "module"
                        ? definitionLabel(row.key, moduleDefinitions)
                        : definitionLabel(row.key, featureDefinitions);
                    return label === row.key ? row.fallback : label;
                  })()}
                  <span className="ml-2 text-[10px] font-medium uppercase tracking-[0.12em] text-zinc-600">
                    {row.type === "module" ? "Modulo" : "Funcion"}
                  </span>
                </td>
                {vendePlans.map((plan) => {
                  const enabled =
                    row.type === "module"
                      ? (plan.modulos_habilitados ?? []).includes(row.key)
                      : (plan.funciones_habilitadas ?? []).includes(row.key);
                  return (
                    <td key={`${plan.id}-${row.key}`} className="px-3 py-3">
                      <VendePlanAccessChip
                        label="Acceso"
                        enabled={enabled}
                      />
                    </td>
                  );
                })}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </section>
  );
}

function EntitlementSummaryPanel({
  entitlements,
  compact = false,
}: {
  entitlements?: PlanEntitlementSummary | null;
  compact?: boolean;
}) {
  if (!entitlements) return null;
  const enabledModules = entitlements.modules.filter((item) => item.enabled);
  const changedItems = [...entitlements.modules, ...entitlements.features].filter(
    (item) => item.source !== "PLAN" || !item.enabled
  );
  const visibleItems = (changedItems.length ? changedItems : enabledModules).slice(
    0,
    compact ? 6 : 10
  );
  return (
    <div className="rounded-2xl border border-cyan-500/15 bg-cyan-500/[0.06] p-4">
      <div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
        <div>
          <p className="text-[11px] uppercase tracking-[0.2em] text-cyan-200/80">
            Entitlements
          </p>
          <p className="mt-2 text-sm leading-6 text-zinc-300">
            {formatNumber(entitlements.modules_count)} modulos y{" "}
            {formatNumber(entitlements.features_count)} funciones efectivas
            {entitlements.has_overrides ? " con ajustes por cliente." : " desde el plan base."}
          </p>
        </div>
        <div className="grid min-w-[180px] grid-cols-2 gap-2 text-xs">
          <div className="rounded-xl border border-white/8 bg-black/20 p-2">
            <p className="text-[10px] uppercase tracking-[0.14em] text-zinc-500">Extras</p>
            <p className="mt-1 font-semibold text-white">
              {formatNumber(
                entitlements.overrides_summary.modulos_agregados +
                  entitlements.overrides_summary.funciones_agregadas
              )}
            </p>
          </div>
          <div className="rounded-xl border border-white/8 bg-black/20 p-2">
            <p className="text-[10px] uppercase tracking-[0.14em] text-zinc-500">Bloqueos</p>
            <p className="mt-1 font-semibold text-white">
              {formatNumber(
                entitlements.overrides_summary.modulos_bloqueados +
                  entitlements.overrides_summary.funciones_bloqueadas
              )}
            </p>
          </div>
        </div>
      </div>
      <div className="mt-3 flex flex-wrap gap-2">
        {entitlements.coverage.map((scope) => (
          <span
            key={scope.scope}
            className="rounded-full border border-white/10 bg-black/20 px-2.5 py-1 text-[10px] font-semibold uppercase tracking-[0.14em] text-zinc-300"
          >
            {entitlementScopeLabel(scope.scope)} · {formatNumber(scope.enabled)}
          </span>
        ))}
      </div>
      {visibleItems.length ? (
        <div className="mt-3 flex flex-wrap gap-2">
          {visibleItems.map((item) => (
            <span
              key={`${item.source}-${item.clave}`}
              className={`rounded-full border px-2.5 py-1 text-[10px] font-semibold uppercase tracking-[0.12em] ${entitlementSourceClasses(item)}`}
              title={item.descripcion}
            >
              {item.nombre} · {entitlementSourceLabel(item)}
            </span>
          ))}
        </div>
      ) : null}
      {entitlements.nota ? (
        <p className="mt-3 text-xs leading-5 text-zinc-500">{entitlements.nota}</p>
      ) : null}
    </div>
  );
}

function diffPlanKeys(before: string[] | undefined, after: string[]) {
  const beforeSet = new Set(before ?? []);
  const afterSet = new Set(after);
  return {
    added: after.filter((key) => !beforeSet.has(key)),
    removed: (before ?? []).filter((key) => !afterSet.has(key)),
  };
}

function applyCapabilityOverrideDraft(base: string[], added: string[], blocked: string[]) {
  const blockedSet = new Set(blocked);
  const resolved = [...base];
  for (const key of added) {
    if (!resolved.includes(key)) resolved.push(key);
  }
  return resolved.filter((key) => !blockedSet.has(key));
}

function capabilityDraftActiveOverrideCount(draft?: CapabilityOverrideDraft | null) {
  if (!draft) return 0;
  return (
    draft.modulos_agregados.length +
    draft.modulos_bloqueados.length +
    draft.funciones_agregadas.length +
    draft.funciones_bloqueadas.length
  );
}

function capabilityDraftHasActiveOverrides(draft?: CapabilityOverrideDraft | null) {
  return capabilityDraftActiveOverrideCount(draft) > 0;
}

function capabilityDraftHasChanges(draft: CapabilityOverrideDraft) {
  return (
    capabilityDraftHasActiveOverrides(draft) ||
    draft.nota.trim().length > 0 ||
    draft.managed_marketing_enabled ||
    draft.managed_marketing_scope.trim().length > 0 ||
    draft.managed_marketing_responsable.trim().length > 0 ||
    draft.managed_marketing_nota.trim().length > 0
  );
}

function managedMarketingScopeLabel(value?: string | null) {
  const option = managedMarketingScopeOptions.find((item) => item.value === value);
  return option?.label || value || "Sin alcance";
}

function managedMarketingNeedsContract(draft: CapabilityOverrideDraft) {
  return (
    draft.managed_marketing_enabled &&
    (!draft.managed_marketing_scope.trim() ||
      !draft.managed_marketing_responsable.trim() ||
      !draft.managed_marketing_nota.trim())
  );
}

function clientHasManagedMarketing(client: SubscriptionItem) {
  return Boolean(client.managed_marketing?.enabled);
}

function capabilityOverrideUpdatedDays(draft?: CapabilityOverrideDraft | null) {
  if (!draft?.actualizado_en) return null;
  const updated = new Date(draft.actualizado_en);
  if (Number.isNaN(updated.getTime())) return null;
  const today = new Date();
  return Math.max(0, Math.floor((today.getTime() - updated.getTime()) / 86_400_000));
}

function capabilityOverrideNeedsNote(client: SubscriptionItem) {
  const overrides = client.plan_capability_overrides;
  return capabilityDraftHasActiveOverrides(overrides) && !(overrides?.nota ?? "").trim();
}

function capabilityOverrideIsStale(client: SubscriptionItem) {
  const days = capabilityOverrideUpdatedDays(client.plan_capability_overrides);
  return capabilityDraftHasActiveOverrides(client.plan_capability_overrides) && (days === null || days >= 30);
}

function CapabilityOverrideImpactPreview({
  client,
  draft,
  moduleDefinitions,
  featureDefinitions,
}: {
  client: SubscriptionItem;
  draft: CapabilityOverrideDraft;
  moduleDefinitions: PlanDefinitionItem[];
  featureDefinitions: PlanDefinitionItem[];
}) {
  const baseModules = client.plan.modulos_habilitados ?? [];
  const baseFeatures = client.plan.funciones_habilitadas ?? [];
  const currentModules = client.effective_plan?.modulos_habilitados ?? baseModules;
  const currentFeatures = client.effective_plan?.funciones_habilitadas ?? baseFeatures;
  const previewModules = applyCapabilityOverrideDraft(
    baseModules,
    draft.modulos_agregados,
    draft.modulos_bloqueados
  );
  const previewFeatures = applyCapabilityOverrideDraft(
    baseFeatures,
    draft.funciones_agregadas,
    draft.funciones_bloqueadas
  );
  const moduleDelta = diffPlanKeys(currentModules, previewModules);
  const featureDelta = diffPlanKeys(currentFeatures, previewFeatures);
  const blockedBaseModules = draft.modulos_bloqueados.filter((key) => baseModules.includes(key));
  const blockedBaseFeatures = draft.funciones_bloqueadas.filter((key) => baseFeatures.includes(key));
  const addedModules = draft.modulos_agregados.filter((key) => !baseModules.includes(key));
  const addedFeatures = draft.funciones_agregadas.filter((key) => !baseFeatures.includes(key));
  const redundantAdds =
    draft.modulos_agregados.filter((key) => baseModules.includes(key)).length +
    draft.funciones_agregadas.filter((key) => baseFeatures.includes(key)).length;
  const riskCount = blockedBaseModules.length + blockedBaseFeatures.length;
  const hasChanges = capabilityDraftHasChanges(draft);
  const tone =
    riskCount > 0
      ? "border-rose-500/20 bg-rose-500/[0.06]"
      : hasChanges
        ? "border-cyan-500/15 bg-cyan-500/[0.05]"
        : "border-white/8 bg-white/[0.03]";
  const action =
    riskCount > 0
      ? "Este override bloquea accesos incluidos en el plan base. Usalo solo con motivo comercial o soporte documentado."
      : hasChanges
        ? "Estos ajustes aplicaran solo a este cliente y no cambian el plan base."
        : "Sin excepciones pendientes: el cliente hereda el plan base completo.";

  const renderKeyList = (
    title: string,
    keys: string[],
    definitions: PlanDefinitionItem[],
    classes: string
  ) => (
    <div className="rounded-2xl border border-white/8 bg-zinc-950/50 p-3">
      <p className="text-[10px] uppercase tracking-[0.16em] text-zinc-500">{title}</p>
      <div className="mt-2 flex flex-wrap gap-1.5">
        {keys.length ? (
          keys.slice(0, 10).map((key) => (
            <span
              key={`${title}-${key}`}
              className={`rounded-full border px-2 py-0.5 text-[10px] font-semibold uppercase tracking-[0.1em] ${classes}`}
            >
              {definitionLabel(key, definitions)}
            </span>
          ))
        ) : (
          <span className="text-xs text-zinc-600">Sin cambios</span>
        )}
      </div>
    </div>
  );

  return (
    <section className={`rounded-2xl border p-4 ${tone}`}>
      <div className="flex flex-col gap-3 lg:flex-row lg:items-start lg:justify-between">
        <div>
          <p className="text-[11px] uppercase tracking-[0.2em] text-cyan-200/80">
            Vista previa de excepcion
          </p>
          <h4 className="mt-1 text-base font-semibold text-white">
            Plan base {client.plan.nombre}
            {" -> "}
            acceso efectivo del cliente
          </h4>
          <p className="mt-2 max-w-3xl text-sm leading-6 text-zinc-400">{action}</p>
        </div>
        <div className="flex flex-wrap gap-2">
          <span className="rounded-full border border-white/10 bg-white/5 px-3 py-1 text-[10px] font-semibold uppercase tracking-[0.14em] text-zinc-300">
            {formatNumber(previewModules.length)} modulos
          </span>
          <span className="rounded-full border border-white/10 bg-white/5 px-3 py-1 text-[10px] font-semibold uppercase tracking-[0.14em] text-zinc-300">
            {formatNumber(previewFeatures.length)} funciones
          </span>
          {redundantAdds > 0 ? (
            <span className="rounded-full border border-amber-500/20 bg-amber-500/10 px-3 py-1 text-[10px] font-semibold uppercase tracking-[0.14em] text-amber-100">
              {formatNumber(redundantAdds)} ya incluidos
            </span>
          ) : null}
        </div>
      </div>

      <div className="mt-4 grid gap-3 md:grid-cols-2">
        {renderKeyList(
          "Extras por cliente",
          [...addedModules, ...addedFeatures],
          [...moduleDefinitions, ...featureDefinitions],
          "border-emerald-500/20 bg-emerald-500/10 text-emerald-100"
        )}
        {renderKeyList(
          "Bloqueos por cliente",
          [...blockedBaseModules, ...blockedBaseFeatures],
          [...moduleDefinitions, ...featureDefinitions],
          "border-rose-500/20 bg-rose-500/10 text-rose-100"
        )}
        {renderKeyList(
          "Se activara al guardar",
          [...moduleDelta.added, ...featureDelta.added],
          [...moduleDefinitions, ...featureDefinitions],
          "border-cyan-500/20 bg-cyan-500/10 text-cyan-100"
        )}
        {renderKeyList(
          "Se desactivara al guardar",
          [...moduleDelta.removed, ...featureDelta.removed],
          [...moduleDefinitions, ...featureDefinitions],
          "border-amber-500/20 bg-amber-500/10 text-amber-100"
        )}
      </div>
    </section>
  );
}

function PlanChangeImpactPreview({
  plan,
  draft,
  clients,
  moduleDefinitions,
  featureDefinitions,
}: {
  plan: PlanItem;
  draft: PlanDraft;
  clients: SubscriptionItem[];
  moduleDefinitions: PlanDefinitionItem[];
  featureDefinitions: PlanDefinitionItem[];
}) {
  const affectedClients = clients.filter((client) => client.plan.id === plan.id);
  const activeClients = affectedClients.filter((client) =>
    ["ACTIVA", "TRIAL", "PAST_DUE"].includes(client.estatus)
  );
  const clientsWithOverrides = affectedClients.filter(
    (client) => client.effective_entitlements?.has_overrides
  );
  const moduleDelta = diffPlanKeys(plan.modulos_habilitados, draft.modulos_habilitados);
  const featureDelta = diffPlanKeys(plan.funciones_habilitadas, draft.funciones_habilitadas);
  const numericChanges = [
    {
      label: "Precio mensual",
      before: formatCurrency(plan.precio_mensual),
      after: formatCurrency(metricNumber(draft.precio_mensual)),
      changed: metricNumber(plan.precio_mensual) !== metricNumber(draft.precio_mensual),
    },
    {
      label: "Precio anual",
      before: formatCurrency(plan.precio_anual),
      after: formatCurrency(metricNumber(draft.precio_anual)),
      changed: metricNumber(plan.precio_anual) !== metricNumber(draft.precio_anual),
    },
    {
      label: "Usuarios",
      before: formatNumber(plan.max_usuarios),
      after: formatNumber(metricNumber(draft.max_usuarios)),
      changed: metricNumber(plan.max_usuarios) !== metricNumber(draft.max_usuarios),
    },
    {
      label: "Entidades",
      before: formatNumber(plan.max_entidades),
      after: formatNumber(metricNumber(draft.max_entidades)),
      changed: metricNumber(plan.max_entidades) !== metricNumber(draft.max_entidades),
    },
    {
      label: "Espacios",
      before: formatNumber(plan.max_espacios),
      after: formatNumber(metricNumber(draft.max_espacios)),
      changed: metricNumber(plan.max_espacios) !== metricNumber(draft.max_espacios),
    },
  ].filter((item) => item.changed);
  const flagChanges = [
    draft.activo !== plan.activo
      ? `Activo: ${plan.activo ? "si" : "no"} -> ${draft.activo ? "si" : "no"}`
      : "",
    draft.es_default !== plan.es_default
      ? `Default: ${plan.es_default ? "si" : "no"} -> ${draft.es_default ? "si" : "no"}`
      : "",
    draft.permite_google_login !== plan.permite_google_login
      ? `Google: ${plan.permite_google_login ? "si" : "no"} -> ${
          draft.permite_google_login ? "si" : "no"
        }`
      : "",
    draft.permite_webhooks !== plan.permite_webhooks
      ? `Webhooks: ${plan.permite_webhooks ? "si" : "no"} -> ${
          draft.permite_webhooks ? "si" : "no"
        }`
      : "",
  ].filter(Boolean);
  const removedTotal = moduleDelta.removed.length + featureDelta.removed.length;
  const addedTotal = moduleDelta.added.length + featureDelta.added.length;
  const hasChanges =
    removedTotal > 0 || addedTotal > 0 || numericChanges.length > 0 || flagChanges.length > 0;
  const tone =
    removedTotal > 0 && activeClients.length > 0
      ? "border-rose-500/20 bg-rose-500/[0.06]"
      : hasChanges
        ? "border-cyan-500/15 bg-cyan-500/[0.05]"
        : "border-white/8 bg-white/[0.03]";
  const action =
    removedTotal > 0 && activeClients.length > 0
      ? "Revisa los clientes activos antes de guardar: se quitaran accesos."
      : hasChanges
        ? "Impacto calculado con el draft actual. Guarda el plan para aplicarlo."
        : "Sin cambios pendientes en capacidades, precios o banderas del plan.";

  const renderDeltaList = (
    title: string,
    keys: string[],
    definitions: PlanDefinitionItem[],
    classes: string
  ) => (
    <div className="rounded-2xl border border-white/8 bg-zinc-950/50 p-3">
      <p className="text-[10px] uppercase tracking-[0.16em] text-zinc-500">{title}</p>
      <div className="mt-2 flex flex-wrap gap-1.5">
        {keys.length ? (
          keys.slice(0, 8).map((key) => (
            <span
              key={`${title}-${key}`}
              className={`rounded-full border px-2 py-0.5 text-[10px] font-semibold uppercase tracking-[0.1em] ${classes}`}
            >
              {definitionLabel(key, definitions)}
            </span>
          ))
        ) : (
          <span className="text-xs text-zinc-600">Sin cambios</span>
        )}
      </div>
    </div>
  );

  return (
    <section className={`rounded-2xl border p-4 ${tone}`}>
      <div className="flex flex-col gap-3 lg:flex-row lg:items-start lg:justify-between">
        <div>
          <p className="text-[11px] uppercase tracking-[0.2em] text-cyan-200/80">
            Simulacion antes de guardar
          </p>
          <h4 className="mt-1 text-base font-semibold text-white">
            {formatNumber(affectedClients.length)} cliente(s) usan este plan
          </h4>
          <p className="mt-2 text-sm leading-6 text-zinc-400">{action}</p>
        </div>
        <div className="flex flex-wrap gap-2">
          <span className="rounded-full border border-white/10 bg-white/5 px-3 py-1 text-[10px] font-semibold uppercase tracking-[0.14em] text-zinc-300">
            {formatNumber(activeClients.length)} activos/trial
          </span>
          {clientsWithOverrides.length ? (
            <span className="rounded-full border border-cyan-500/20 bg-cyan-500/10 px-3 py-1 text-[10px] font-semibold uppercase tracking-[0.14em] text-cyan-100">
              {formatNumber(clientsWithOverrides.length)} con overrides
            </span>
          ) : null}
        </div>
      </div>

      <div className="mt-4 grid gap-3 md:grid-cols-2">
        {renderDeltaList(
          "Modulos agregados",
          moduleDelta.added,
          moduleDefinitions,
          "border-emerald-500/20 bg-emerald-500/10 text-emerald-100"
        )}
        {renderDeltaList(
          "Modulos removidos",
          moduleDelta.removed,
          moduleDefinitions,
          "border-rose-500/20 bg-rose-500/10 text-rose-100"
        )}
        {renderDeltaList(
          "Funciones agregadas",
          featureDelta.added,
          featureDefinitions,
          "border-cyan-500/20 bg-cyan-500/10 text-cyan-100"
        )}
        {renderDeltaList(
          "Funciones removidas",
          featureDelta.removed,
          featureDefinitions,
          "border-amber-500/20 bg-amber-500/10 text-amber-100"
        )}
      </div>

      {numericChanges.length || flagChanges.length ? (
        <div className="mt-4 grid gap-3 md:grid-cols-2">
          {numericChanges.length ? (
            <div className="rounded-2xl border border-white/8 bg-zinc-950/50 p-3">
              <p className="text-[10px] uppercase tracking-[0.16em] text-zinc-500">
                Precios y limites
              </p>
              <div className="mt-2 space-y-1 text-xs text-zinc-400">
                {numericChanges.map((item) => (
                  <p key={item.label}>
                    {item.label}: <span className="text-zinc-500">{item.before}</span>
                    {" -> "}
                    <span className="text-cyan-100">{item.after}</span>
                  </p>
                ))}
              </div>
            </div>
          ) : null}
          {flagChanges.length ? (
            <div className="rounded-2xl border border-white/8 bg-zinc-950/50 p-3">
              <p className="text-[10px] uppercase tracking-[0.16em] text-zinc-500">
                Banderas del plan
              </p>
              <div className="mt-2 space-y-1 text-xs text-zinc-400">
                {flagChanges.map((item) => (
                  <p key={item}>{item}</p>
                ))}
              </div>
            </div>
          ) : null}
        </div>
      ) : null}

      {affectedClients.length ? (
        <div className="mt-4 rounded-2xl border border-white/8 bg-zinc-950/50 p-3">
          <p className="text-[10px] uppercase tracking-[0.16em] text-zinc-500">
            Clientes impactados
          </p>
          <div className="mt-2 flex flex-wrap gap-1.5">
            {affectedClients.slice(0, 8).map((client) => (
              <span
                key={client.id}
                className="rounded-full border border-white/10 bg-white/[0.04] px-2 py-0.5 text-[10px] font-semibold uppercase tracking-[0.1em] text-zinc-300"
              >
                {client.capa_negocio.nombre}
              </span>
            ))}
            {affectedClients.length > 8 ? (
              <span className="rounded-full border border-white/10 bg-white/[0.04] px-2 py-0.5 text-[10px] font-semibold uppercase tracking-[0.1em] text-zinc-500">
                +{formatNumber(affectedClients.length - 8)}
              </span>
            ) : null}
          </div>
        </div>
      ) : null}
    </section>
  );
}

function clientUsageStatus(client: SubscriptionItem) {
  const ratios = clientCapacityMetrics(client).map((metric) =>
    usageRatio(metric.used, metric.limit)
  );
  const maxRatio = Math.max(...ratios);
  if (maxRatio > 1 || client.estatus === "PAST_DUE") {
    return {
      level: "EXCEDIDO",
      label: client.estatus === "PAST_DUE" ? "Pago vencido" : "Excede plan",
      className: "border-rose-500/25 bg-rose-500/10 text-rose-200",
    };
  }
  if (maxRatio >= 0.8) {
    return {
      level: "PREVENTIVA",
      label: "Cerca del limite",
      className: "border-amber-500/25 bg-amber-500/10 text-amber-200",
    };
  }
  return {
    level: "OK",
    label: "Uso sano",
    className: "border-emerald-500/20 bg-emerald-500/10 text-emerald-200",
  };
}

function customerHealthStatus(client: SubscriptionItem) {
  if (client.health) {
    if (client.health.status === "ERROR") {
      return {
        level: "ERROR",
        label: "Critico",
        className: "border-rose-500/25 bg-rose-500/10 text-rose-200",
      };
    }
    if (client.health.status === "WARN") {
      return {
        level: "WARN",
        label: "Atencion",
        className: "border-amber-500/25 bg-amber-500/10 text-amber-200",
      };
    }
    return {
      level: "OK",
      label: "Sano",
      className: "border-emerald-500/20 bg-emerald-500/10 text-emerald-200",
    };
  }
  const usageStatus = clientUsageStatus(client);
  return {
    level: usageStatus.level === "OK" ? "OK" : "WARN",
    label: usageStatus.label,
    className: usageStatus.className,
  };
}

function customerHealthDomainClasses(status?: string) {
  if (status === "ERROR") {
    return "border-rose-500/25 bg-rose-500/10 text-rose-200";
  }
  if (status === "WARN") {
    return "border-amber-500/25 bg-amber-500/10 text-amber-200";
  }
  return "border-emerald-500/20 bg-emerald-500/10 text-emerald-200";
}

