function planStripePriceId(
  plan: PlanItem,
  periodicidad: string,
  stripeMode: "TEST" | "LIVE"
) {
  if (periodicidad === "ANUAL") {
    return stripeMode === "LIVE"
      ? plan.stripe_price_id_anual
      : plan.stripe_test_price_id_anual;
  }
  return stripeMode === "LIVE"
    ? plan.stripe_price_id_mensual
    : plan.stripe_test_price_id_mensual;
}

