function prospectFirstName(name: string) {
  return (name || "").trim().split(/\s+/)[0] || "";
}

function normalizeLowerLabel(value?: string | null) {
  return (value || "").trim().toLowerCase();
}

function marketingProspectPainCopy(qualification: LeadQualification) {
  const pain = (qualification.main_pain || "").trim();
  if (pain === "overdue_accounts") {
    return "cuentas vencidas y recordatorios de cobranza";
  }
  if (pain === "pending_rents") {
    return "rentas pendientes y seguimiento de pagos";
  }
  if (pain === "unregistered_payments") {
    return "pagos realizados pero no registrados";
  }
  if (pain === "self_service") {
    return "autoservicio para que el cliente consulte saldos, comprobantes y facturas";
  }
  if (pain === "real_time_control") {
    return "control del negocio e informacion en tiempo real";
  }
  return "cobranza, espacios, clientes y control operativo";
}

function formatMarketingProspectFollowup(prospect: ProspectItem) {
  const qualification = prospect.lead_qualification ?? {};
  const firstName = prospectFirstName(prospect.nombre);
  const greeting = firstName ? `Hola ${firstName}` : "Hola";
  const operation = normalizeLowerLabel(qualification.operation_type_label) || "espacios en renta";
  const spaces = normalizeLowerLabel(qualification.spaces_count_label);
  const collection = normalizeLowerLabel(qualification.collection_method_label);
  const urgency = normalizeLowerLabel(qualification.urgency_label);
  const painCopy = marketingProspectPainCopy(qualification);
  const contextParts = [
    `para ${operation}`,
    spaces ? `con ${spaces}` : "",
    collection ? `y cobranza por ${collection}` : "",
  ].filter(Boolean);
  const urgencyLine =
    urgency && urgency !== "solo explorando"
      ? `Como quieres resolverlo ${urgency}, te propongo priorizar una demo corta.`
      : "Te propongo una demo corta para revisar si encaja con tu operacion.";

  return [
    `${greeting}, soy del equipo de BetterP.`,
    "",
    `Vi que te interesa Renta Facil ${contextParts.join(" ")}.`,
    `Podemos enfocarnos en ${painCopy}: recordatorios, pagos pendientes, pagos no registrados, autoservicio y control en tiempo real desde un solo sistema.`,
    "",
    `${urgencyLine} En 15 minutos revisamos tu caso y te digo con claridad si Renta Facil te ayuda o si no es el mejor momento.`,
    "",
    "Que dia te queda mejor para verlo?",
  ].join("\n");
}

function normalizeMarketingProspectPhone(phone?: string | null) {
  const digits = (phone || "").replace(/\D/g, "");
  if (!digits) return "";
  if (digits.length === 10) return `52${digits}`;
  if (digits.length === 11 && digits.startsWith("1")) return `52${digits.slice(1)}`;
  return digits;
}

function marketingProspectWhatsAppUrl(prospect: ProspectItem) {
  const phone = normalizeMarketingProspectPhone(prospect.telefono);
  if (!phone) return "";
  return `https://wa.me/${phone}?text=${encodeURIComponent(
    formatMarketingProspectFollowup(prospect)
  )}`;
}

function marketingProspectEmailUrl(prospect: ProspectItem) {
  const email = (prospect.email || "").trim();
  if (!email) return "";
  const subject = `Demo Renta Facil - ${prospect.empresa || prospect.nombre || "prospecto"}`;
  return `mailto:${email}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(
    formatMarketingProspectFollowup(prospect)
  )}`;
}

function marketingProspectContactNote(prospect: ProspectItem) {
  const qualification = prospect.lead_qualification ?? {};
  const quality = qualification.quality ? `Lead ${qualification.quality}` : "Lead MKT";
  const pain = qualification.main_pain_label || marketingProspectPainCopy(qualification);
  const urgency = qualification.urgency_label ? ` Urgencia: ${qualification.urgency_label}.` : "";
  return `${quality}. Primer contacto enviado desde Backoffice MKT. Dolor: ${pain}.${urgency}`;
}

function marketingProspectDemoNote(prospect: ProspectItem) {
  const qualification = prospect.lead_qualification ?? {};
  const pain = qualification.main_pain_label || marketingProspectPainCopy(qualification);
  const operation = qualification.operation_type_label || "espacios en renta";
  const spaces = qualification.spaces_count_label ? ` Volumen: ${qualification.spaces_count_label}.` : "";
  return `Demo agendada desde Backoffice MKT. Enfocar recorrido en ${pain} para ${operation}.${spaces}`;
}

function marketingProspectProposalNote(prospect: ProspectItem) {
  const qualification = prospect.lead_qualification ?? {};
  const pain = qualification.main_pain_label || marketingProspectPainCopy(qualification);
  const operation = qualification.operation_type_label || "espacios en renta";
  const urgency = qualification.urgency_label ? ` Urgencia declarada: ${qualification.urgency_label}.` : "";
  return `Propuesta solicitada desde Backoffice MKT. Preparar oferta Renta Facil para ${operation}, enfocada en ${pain}.${urgency}`;
}

function marketingProspectLostNote(prospect: ProspectItem, lostReason = "") {
  const qualification = prospect.lead_qualification ?? {};
  const pain = qualification.main_pain_label || marketingProspectPainCopy(qualification);
  const operation = qualification.operation_type_label || "espacios en renta";
  const objection = lostReason.trim()
    ? ` Objecion principal: ${lostReason.trim()}.`
    : " Registrar objecion concreta en Solicitudes si existe.";
  return `Oportunidad marcada como perdida desde Backoffice MKT. Contexto: ${operation}, dolor principal ${pain}.${objection}`;
}

function dateStamp() {
  return new Date().toISOString().slice(0, 10);
}

function nextDateStamp(days = 1) {
  const date = new Date();
  date.setDate(date.getDate() + days);
  return date.toISOString().slice(0, 10);
}

function toggleStringValue(values: string[], value: string, checked: boolean) {
  if (checked) {
    return values.includes(value) ? values : [...values, value];
  }
  return values.filter((item) => item !== value);
}

function resolveDefinitionNames(keys: string[] | undefined, definitions: PlanDefinitionItem[]) {
  if (!keys?.length) return "";
  const definitionMap = new Map(definitions.map((item) => [item.clave, item.nombre]));
  return keys.map((key) => definitionMap.get(key) || key).join(", ");
}

function definitionLabel(key: string, definitions: PlanDefinitionItem[]) {
  return definitions.find((item) => item.clave === key)?.nombre || key;
}

function sortedVendePlans(plans: PlanItem[]) {
  return plans
    .filter((plan) => isVendeFacilPlan(plan))
    .sort((a, b) => {
      const priceDiff = Number(a.precio_mensual || 0) - Number(b.precio_mensual || 0);
      if (priceDiff !== 0) return priceDiff;
      return Number(a.solution_profile?.commercial_limits.productos ?? a.max_espacios) -
        Number(b.solution_profile?.commercial_limits.productos ?? b.max_espacios);
    });
}

function nextVendePlanForClient(client: SubscriptionItem, plans: PlanItem[]) {
  const vendePlans = sortedVendePlans(plans).filter((plan) => plan.activo);
  const currentIndex = vendePlans.findIndex((plan) => plan.id === client.plan.id);
  if (currentIndex >= 0 && currentIndex < vendePlans.length - 1) {
    return vendePlans[currentIndex + 1];
  }
  const currentPrice = Number(client.plan.precio_mensual || 0);
  return vendePlans.find((plan) => Number(plan.precio_mensual || 0) > currentPrice) || null;
}

function planDelta(currentClient: SubscriptionItem, nextPlan: PlanItem | null) {
  if (!nextPlan) {
    return { modules: [] as string[], features: [] as string[] };
  }
  const currentModules = new Set(effectivePlanModules(currentClient));
  const currentFeatures = new Set(effectivePlanFeatures(currentClient));
  return {
    modules: (nextPlan.modulos_habilitados ?? []).filter((key) => !currentModules.has(key)),
    features: (nextPlan.funciones_habilitadas ?? []).filter((key) => !currentFeatures.has(key)),
  };
}

function vendeCommercialSignals(client: SubscriptionItem) {
  const capacity = client.solution_usage?.capacity ?? [];
  const critical = capacity.filter((item) => item.status === "ERROR");
  const warning = capacity.filter((item) => item.status === "WARN");
  const summary = client.solution_usage?.summary ?? {};
  const signals: string[] = [];
  if (critical.length) {
    signals.push(`${critical[0].label} excedido`);
  } else if (warning.length) {
    signals.push(`${warning[0].label} cerca del limite`);
  }
  const channelLimit = metricNumber(client.solution_usage?.limits?.canales);
  if (channelLimit > 0 && metricNumber(summary.canales_configurados) >= channelLimit) {
    signals.push("Canales al limite");
  }
  if (metricNumber(summary.incidencias_calidad_bloqueantes) > 0) {
    signals.push("Calidad bloqueante");
  }
  return signals.slice(0, 3);
}

