function legacyVisualStrategy(formatKey?: string) {
  if (formatKey === "infografia_3_puntos") {
    return {
      mode: "simple_ad_story",
      label: "Simple ad story",
      prompt_rule:
        "Visual mode: simple ad story. Use a clean problem-solution-result layout, one main headline, one support line, and no more than four major visual objects. The design may be editorial, playful infographic, or premium dark/cyan if it explains the idea faster.",
      text_policy: "Exactly one headline and one short support line; no other visible words.",
    };
  }
  if (formatKey === "checklist") {
    return {
      mode: "compact_checklist",
      label: "Compact checklist",
      prompt_rule:
        "Visual mode: compact checklist. Use one diagnostic question, two clean cues, and a large empty-space-to-control contrast.",
      text_policy: "One short question and two cue labels maximum.",
    };
  }
  if (formatKey === "sabias_que") {
    return {
      mode: "data_snap",
      label: "Data snap",
      prompt_rule:
        "Visual mode: data snap. Show one surprising operational insight with one big number or status, a simple scene, and no decorative metrics.",
      text_policy: "One short headline and one tiny data cue only.",
    };
  }
  if (formatKey === "antes_despues") {
    return {
      mode: "hybrid_story",
      label: "Hybrid before/after",
      prompt_rule:
        "Visual mode: hybrid story. Split the image into two visually distinct zones: scattered work before, connected control after. Make the contrast memorable without turning it into a dashboard wall.",
      text_policy: "Two labels maximum: before and after.",
    };
  }
  return {
    mode: "storytelling_case",
    label: "Story-led case",
    prompt_rule:
      "Visual mode: story-led case. Tell the case through one real-world scene and one BetterP action, not through equations, crowded dashboards, or explanatory text.",
    text_policy: "Mostly no text; at most one short headline or one small status badge.",
  };
}

function marketingVisualSupportLine(campaign: MarketingCampaignItem) {
  const pillarKey =
    campaign.metadata?.editorial_matrix?.pillar?.key ||
    campaign.metadata?.content_pillar ||
    "";
  if (pillarKey === "vacancy_revenue") {
    return "BetterP publica y promueve espacios para agilizar la renta y acercarte a tus próximos clientes.";
  }
  if (pillarKey === "admin_hours") {
    return "Publicaciones, pagos y facturas en un solo sistema.";
  }
  if (pillarKey === "client_self_service") {
    return "Datos fiscales, facturas, comprobantes y saldos a un click.";
  }
  if (pillarKey === "automated_collections") {
    return "Recordatorios por WhatsApp para cuidar cartera vencida y flujo de efectivo.";
  }
  if (pillarKey === "real_time_control") {
    return "BetterP concentra datos para decidir a tiempo.";
  }
  if (pillarKey === "unit_profitability") {
    return "Balance por edificio, cabaña, casa, habitación o unidad.";
  }
  return "BetterP conecta la operación para vender y controlar mejor.";
}

function marketingVisualCoreMessage(campaign: MarketingCampaignItem) {
  const pillarKey =
    campaign.metadata?.editorial_matrix?.pillar?.key ||
    campaign.metadata?.content_pillar ||
    "";
  if (pillarKey === "vacancy_revenue") {
    return "Core message: an empty rental space costs money. BetterP publishes and promotes available spaces so the owner can reach qualified rental prospects faster.";
  }
  if (pillarKey === "admin_hours") {
    return "Core message: manual collections, invoices, and payment proof reviews consume admin hours. BetterP organizes the flow so the team spends less time chasing payments.";
  }
  if (pillarKey === "client_self_service") {
    return "Core message: customer service consumes time when every invoice, payment proof, or balance request depends on a message or email. BetterP gives customers a portal to update fiscal data, download invoices, upload payment proofs, and check account status in one click.";
  }
  if (pillarKey === "automated_collections") {
    return "Core message: manual rent collection works until the operation grows and overdue payments accumulate. BetterP sends WhatsApp reminders before, during, and after the due date, records payments, and keeps collections under automated control to protect cash flow.";
  }
  if (pillarKey === "real_time_control") {
    return "Core message: late reports delay decisions. BetterP brings income, overdue balances, expenses, and occupancy into one readable operational view.";
  }
  if (pillarKey === "unit_profitability") {
    return "Core message: weak work tools make it hard to know whether the business is growing or just consuming time and resources. BetterP shows a balance per business unit so the owner can identify where the operation actually has gains.";
  }
  return "Core message: BetterP connects commercial and administrative work so the business operates with more control.";
}

function marketingVisualLayoutLines(campaign: MarketingCampaignItem, visualMode: string) {
  const editorialMatrix = campaign.metadata?.editorial_matrix;
  const pillarKey =
    editorialMatrix?.pillar?.key ||
    campaign.metadata?.content_pillar ||
    "";
  const formatKey =
    campaign.metadata?.creative_brief?.format_key ||
    editorialMatrix?.creative_format?.key ||
    "";
  if (pillarKey === "vacancy_revenue" && visualMode === "simple_ad_story") {
    return [
      "Preferred visual style for this vacancy piece: bright white editorial SaaS ad, premium real-estate photography mixed with clean product UI, airy spacing, soft blue/cyan gradients, subtle curved white dividers, and a polished BetterP brand lockup.",
      "Typography direction: large dark-navy headline in the top white area, support line directly underneath, generous margins, no tiny labels.",
      "Use this exact layout for this piece: top 30-35% clean white typography area; bottom 65-70% a three-panel triptych. Left panel: a modern empty rentable space with a small red calendar or sad vacancy cue. Center panel: a laptop/tablet or floating BetterP listing card showing the space being published and promoted automatically. Right panel: warm business-real-estate scene with interested tenants/prospects, a consultation, handshake, phone inquiry, or green check signal.",
      "Keep this vacancy composition calm and literal: one empty space, one BetterP publishing card, one group of interested prospects. Use simple arrows or subtle blue light trails only between panels.",
    ];
  }
  if (pillarKey === "client_self_service") {
    return [
      "Preferred visual style for this client self-service piece: friendly premium B2B infographic, clean but not boring, with customer-service time saved as the main story and a client portal as the hero.",
      "Story: managing rental spaces consumes time when invoices, payment proofs, balances, and fiscal data arrive by messages or email. BetterP gives the customer a self-service portal to solve those tasks in one click.",
      "Composition: center a polished portal card with four large modules: Datos fiscales, Facturas, Comprobantes, Estado de cuenta. Show fewer icons, more clarity, and a calm customer experience.",
      "Keep the admin team in the background with fewer repeated customer-service messages; show relief through a clean check signal, not through crowded chats.",
    ];
  }
  if (pillarKey === "automated_collections") {
    return [
      "Preferred visual style for this automated-collections piece: dynamic but readable timeline infographic, premium dark/cyan or hybrid, with overdue payments and cash-flow protection as the central story.",
      "Story: manual collection works until due dates and overdue payments accumulate; with BetterP, reminders go out before, during, and after the due date, and payments are recorded automatically.",
      "Composition: use a simple three-step timeline with neutral chat bubbles inspired by messaging, overdue-payment cues, a cash-flow or cartera-vencida indicator, and a control board that confirms registered payments. Do not use the official WhatsApp logo.",
      "Make the outcome obvious: fewer overdue payments accumulating, cleaner cash flow, and automated collection control.",
    ];
  }
  if (pillarKey === "unit_profitability") {
    return [
      "Preferred visual style for this unit-profitability piece: elegant operational finance infographic with business-unit cards, warm real-estate context, and BetterP control layer.",
      "Story: the old tools do not help the owner control the operation, so it is hard to see which unit grows and which one consumes more time and resources. BetterP turns each unit into a clear balance.",
      "Composition: show 3 or 4 large unit cards such as edificio, cabaña, casa, habitación, or espacio, with simple signals for ingreso, recursos consumidos, compromiso, and ganancia. Avoid a dense dashboard.",
      "Use the visual question as the emotional center: where does this operation really have gains?",
    ];
  }
  if (pillarKey === "admin_hours") {
    return [
      "Preferred visual style for this admin-hours piece: energetic before/after infographic, playful but premium B2B SaaS, with a deep navy-to-cyan gradient or a bright/cool hybrid background. Do not make it a flat white dashboard.",
      "Story: left side labeled 'Antes' shows manual work taking too long: a social post card, an Excel-like payment sheet, loose payment proof, manual invoice paper, and an hourglass. Right side labeled 'Con BetterP' shows one integrated BetterP system with three clear modules: Publicaciones, Pagos, Facturas.",
      "Use one strong flow arrow or blue light stream from manual chaos into the BetterP system. Make the idea fun, concise, and understandable at a glance.",
      "On-image text suggestion for this concept: headline 'Menos trabajo manual. Más control.' support line 'Publicaciones, pagos y facturas en un solo sistema.'",
    ];
  }
  if (visualMode === "compact_checklist" || formatKey === "checklist") {
    return [
      "Preferred visual style for this checklist: clean but memorable infographic, one strong diagnostic question, two or three large checklist cards, generous spacing, and simple cyan/green status cues. It can be bright white or cool dark/cyan if that makes the idea clearer.",
      "Composition: readable checklist or self-audit layout. Avoid photo clutter; make it useful to save or share.",
    ];
  }
  if (visualMode === "data_snap" || formatKey === "sabias_que") {
    return [
      "Preferred visual style for this data snap: one big insight or number, one supporting scene, and a clean data card with personality. Use contrast and color intentionally; avoid generic flat white unless the insight needs it.",
      "Composition: editorial infographic with a single focal metric; no dashboard wall or dense chart grid.",
    ];
  }
  if (visualMode === "hybrid_story" || formatKey === "antes_despues") {
    return [
      "Preferred visual style for this before/after story: two clear zones with a simple contrast between scattered work before and connected control after. The design can be white editorial, dark/cyan premium, or hybrid, as long as the transformation is obvious.",
      "Composition: visual comparison, not a full dashboard. Keep labels minimal and make the transformation obvious.",
    ];
  }
  return [
    "Preferred visual style: clean B2B SaaS editorial image or well-made infographic depending on the campaign format, with generous spacing, a single idea, and a design with enough personality to stop the scroll.",
    "Composition: make the problem, BetterP action, and result visible without crowding the image.",
  ];
}

function shouldUpgradeMarketingImagePrompt(prompt?: string | null) {
  if (!prompt) return false;
  const lowered = prompt.toLowerCase();
  return [
    "abstract channel cards",
    "owner dashboard",
    "busy dashboard",
    "centralizes incoming inquiries",
    "centraliza interesados",
    "not published and promoted in time",
    "one BetterP publishing action, one rental/inquiry result",
    "use this exact layout: top 30-35% clean white typography area",
    "visual hierarchy do the work",
    "2 or 3 visual zones maximum",
    "qualified inquiries/bookings flowing back",
    "no dark background",
    "antes disperso",
    "betterp concentra datos para decidir a tiempo",
  ].some((marker) => lowered.includes(marker));
}

function marketingVisualHeadline(campaign: MarketingCampaignItem) {
  const pillarKey =
    campaign.metadata?.editorial_matrix?.pillar?.key ||
    campaign.metadata?.content_pillar ||
    "";
  if (pillarKey === "client_self_service") {
    return "Autoservicio para clientes. Todo a un click.";
  }
  if (pillarKey === "automated_collections") {
    return "Cobranza automática. Flujo bajo control.";
  }
  if (pillarKey === "unit_profitability") {
    return "Control por unidad. Ganancias claras.";
  }
  if (pillarKey === "admin_hours") {
    return "Menos trabajo manual. Más control.";
  }
  return campaign.metadata?.creative_brief?.title || campaign.titulo;
}

function buildLegacyMarketingImagePrompt(campaign: MarketingCampaignItem) {
  const metadata = campaign.metadata ?? {};
  const creativeBrief = metadata.creative_brief;
  const editorialMatrix = metadata.editorial_matrix;
  const formatKey = creativeBrief?.format_key || editorialMatrix?.creative_format?.key;
  const visualStrategy =
    creativeBrief?.visual_strategy ||
    editorialMatrix?.visual_strategy ||
    legacyVisualStrategy(formatKey);
  const visualRule =
    visualStrategy.prompt_rule ||
    "Visual mode: hybrid story. Keep the concept clear, visual, and easy to scan.";
  const visualMode = visualStrategy.mode || "hybrid_story";
  const visualTextPolicy = visualStrategy.text_policy || "Minimal text only.";
  const segment =
    creativeBrief?.segment ||
    editorialMatrix?.segment?.label ||
    metadata.segment ||
    "espacios e inmuebles en renta";
  const pillar =
    creativeBrief?.pillar ||
    editorialMatrix?.pillar?.label ||
    metadata.content_pillar ||
    "dinero, tiempo y control recuperable";
  const direction =
    creativeBrief?.direction ||
    editorialMatrix?.creative_format?.direction ||
    "Infografia limpia, ejecutiva y legible en movil.";
  const points = (creativeBrief?.points ?? []).filter(Boolean).slice(0, 3);
  const visualPoints =
    points.length > 0
      ? points.join("; ")
      : campaign.resumen || "vacant space, automated listings, qualified inquiries";
  const supportLine = marketingVisualSupportLine(campaign);
  const cta = editorialMatrix?.recommended_cta || campaign.cta_texto || "Solicitar demo de Renta Facil";
  const objection =
    editorialMatrix?.objection ||
    metadata.learning_experiment?.objection_to_address ||
    "La operacion dispersa parece normal hasta que se mide el dinero detenido.";
  const visualLayoutLines = marketingVisualLayoutLines(campaign, visualMode);

  return [
    "Create a premium square 1:1 social image for BetterP / Renta Facil.",
    "Primary rule: make it understandable in 3 seconds. This is a direct-response business ad; infographics are welcome when they explain one idea clearly, but never make decorative SaaS filler.",
    visualRule,
    `Visual strategy key: ${visualMode}.`,
    marketingVisualCoreMessage(campaign),
    `Audience: ${segment.toLowerCase()}. Business angle: ${pillar.toLowerCase()}.`,
    ...visualLayoutLines,
    `Use these as conceptual story beats only, not as labels: ${visualPoints}.`,
    `Commercial friction to reduce: ${objection}.`,
    `Visual format and composition: ${direction}`,
    `CTA should be implied visually as a small clean action area, not rendered as a long sentence: ${cta}.`,
    `On-image text policy: ${visualTextPolicy} Main Spanish headline: "${marketingVisualHeadline(campaign)}". Support line: "${supportLine}". If text rendering is uncertain, reserve clean negative space for these two lines and do not invent other text.`,
    "Do not render paragraphs, formulas, mini-case labels, tiny captions, equations, feature lists, or extra explanations.",
    "Brand identity: modern B2B SaaS, clean, trustworthy, premium, with BetterP cyan/blue accents, restrained green only for positive signals, high contrast, generous spacing, and clear hierarchy.",
    "Creative direction: choose the visual style that best sells this specific idea. Do not default every image to flat white; white editorial works for some vacancy pieces, while operational pieces can use a cooler deep navy/cyan look if it stays readable and premium.",
    "Logo: use the attached BetterP logo as reference; place it visible but discreet, preferably bottom-right or as a final lockup. Do not redraw it, distort it, recolor it, or repeat it as a pattern.",
    "Composition constraints: no giant dashboard wall, no gloomy black void, no dense infographic grid, no charts, no icon stacks, no glowing web of connectors, no futuristic control room.",
    "Do not include third-party platform logos; represent publishing channels only as simple neutral cards if needed.",
    "Negative prompt: saturated or confusing infographic, overdone neon UI, busy dashboard screenshots, many icons, many arrows, complex UI, tiny text, misspelled labels, third-party logos, flying money, generic stock ad, guaranteed-results claims, cluttered composition.",
    "Desired output: PNG 1080x1080, high contrast, mobile-legible, polished enough for Facebook and Instagram publication.",
  ].join("\n");
}

function normalizeMarketingReviewText(...values: Array<string | null | undefined>) {
  return values
    .filter(Boolean)
    .join(" ")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase();
}

function marketingTextHasAny(text: string, terms: string[]) {
  return terms.some((term) => text.includes(term));
}

function evaluateMarketingCreativeConsistency(
  campaign: MarketingCampaignItem,
  imagePrompt: string,
  hasVisualAsset: boolean
) {
  const campaignText = normalizeMarketingReviewText(
    campaign.titulo,
    campaign.resumen,
    campaign.oferta,
    campaign.copy,
    campaign.cta_texto,
    campaign.cta_url,
    imagePrompt
  );
  const promptText = normalizeMarketingReviewText(imagePrompt);
  const checks = [
    {
      label: "Dolor económico visible",
      detail: "La pieza debe hablar de dinero, vacancia o ingreso detenido.",
      ok: marketingTextHasAny(campaignText, [
        "dinero",
        "ingreso",
        "vacancia",
        "vacio",
        "vacios",
        "perder",
        "perdida",
        "ocupacion",
      ]),
    },
    {
      label: "Publicación automatizada",
      detail: "Debe quedar claro que BetterP ayuda a publicar espacios disponibles.",
      ok: marketingTextHasAny(campaignText, [
        "publica",
        "publicacion",
        "espacios disponibles",
        "canales",
        "mercado libre",
        "metros cubicos",
        "facebook",
        "instagram",
        "visibilidad",
      ]),
    },
    {
      label: "Identidad BetterP",
      detail: "El prompt o la pieza debe preservar marca, logo y acentos visuales.",
      ok: marketingTextHasAny(campaignText, ["betterp", "logo", "cyan", "blue", "brand"]),
    },
    {
      label: "Texto visual controlado",
      detail: "La imagen debe contar la historia sin depender de párrafos o fórmulas.",
      ok: marketingTextHasAny(promptText, [
        "mostly no text",
        "minimal text",
        "negative space",
        "micro-label",
        "do not render paragraphs",
        "never a text-heavy poster",
      ]),
    },
    {
      label: "Oferta o CTA conectada",
      detail: "Debe existir una salida comercial clara hacia demo, prueba u oferta.",
      ok: marketingTextHasAny(campaignText, [
        "demo",
        "agenda",
        "gratis",
        "descuento",
        "devolucion",
        "cta",
        "contacto",
      ]),
    },
    {
      label: "Imagen cargada",
      detail: "La publicación necesita un creativo real antes de salir.",
      ok: hasVisualAsset,
    },
  ];
  const passed = checks.filter((check) => check.ok).length;
  const score = Math.round((passed / checks.length) * 100);
  return {
    checks,
    score,
    verdict:
      score >= 84
        ? "Lista para revisión final"
        : score >= 67
          ? "Prometedora, revisar ajustes visuales"
          : "Necesita pulirse antes de publicar",
  };
}

function shellCardClass(extra = "") {
  return `rounded-[28px] border border-white/8 bg-zinc-950/70 shadow-[0_20px_80px_rgba(0,0,0,0.24)] ${extra}`;
}

function metricCardClass(color: string) {
  return `${shellCardClass(
    "p-5"
  )} bg-gradient-to-br ${color}`;
}

function IconBox({
  tone = "cyan",
  children,
}: {
  tone?: "cyan" | "emerald" | "violet" | "amber" | "rose";
  children: ReactNode;
}) {
  const classes =
    tone === "emerald"
      ? "border-emerald-500/20 bg-emerald-500/10 text-emerald-200"
      : tone === "violet"
        ? "border-violet-500/20 bg-violet-500/10 text-violet-200"
        : tone === "amber"
          ? "border-amber-500/20 bg-amber-500/10 text-amber-200"
          : tone === "rose"
            ? "border-rose-500/20 bg-rose-500/10 text-rose-200"
            : "border-cyan-500/20 bg-cyan-500/10 text-cyan-200";
  return (
    <span className={`inline-flex h-11 w-11 items-center justify-center rounded-2xl border ${classes}`}>
      {children}
    </span>
  );
}

function ActionIconButton({
  label,
  tone = "cyan",
  size = "default",
  disabled = false,
  onClick,
  children,
}: {
  label: string;
  tone?: "cyan" | "blue" | "emerald" | "amber" | "violet" | "rose";
  size?: "default" | "sm";
  disabled?: boolean;
  onClick: () => void;
  children: ReactNode;
}) {
  const toneClass =
    tone === "blue"
      ? "border-blue-500/20 bg-blue-500/10 text-blue-100 hover:border-blue-400/40 hover:bg-blue-500/15"
      : tone === "emerald"
        ? "border-emerald-500/20 bg-emerald-500/10 text-emerald-100 hover:border-emerald-400/40 hover:bg-emerald-500/15"
        : tone === "amber"
          ? "border-amber-500/20 bg-amber-500/10 text-amber-100 hover:border-amber-400/40 hover:bg-amber-500/15"
      : tone === "violet"
        ? "border-violet-500/20 bg-violet-500/10 text-violet-100 hover:border-violet-400/40 hover:bg-violet-500/15"
        : tone === "rose"
          ? "border-rose-500/20 bg-rose-500/10 text-rose-100 hover:border-rose-400/40 hover:bg-rose-500/15"
          : "border-cyan-500/20 bg-cyan-500/10 text-cyan-100 hover:border-cyan-400/40 hover:bg-cyan-500/15";
  const sizeClass = size === "sm" ? "h-9 w-9 rounded-xl" : "h-11 w-11 rounded-2xl";

  return (
    <button
      type="button"
      title={label}
      aria-label={label}
      onClick={onClick}
      disabled={disabled}
      className={`inline-flex items-center justify-center border transition disabled:cursor-not-allowed disabled:opacity-60 ${sizeClass} ${toneClass}`}
    >
      {children}
    </button>
  );
}

