  async function fetchJson<T>(path: string): Promise<T> {
    const response = await fetch(buildApiUrl(path), {
      method: "GET",
      cache: "no-store",
    });
    const body = await readJson<T & { detail?: string }>(response);
    if (!response.ok) {
      throw new Error((body as { detail?: string }).detail || "No se pudo cargar el backoffice.");
    }
    return body as T;
  }

  async function handleIssueSaasInvoice(subscriptionId: number) {
    setNotice("");
    setErrorMessage("");
    setInvoicingSubscriptionId(subscriptionId);
    try {
      const response = await fetch(
        buildApiUrl(`/facturacion/backoffice/suscripciones/${subscriptionId}/emitir/`),
        { method: "POST" }
      );
      const body = await readJson<{
        detail?: string;
        mensaje?: string;
        factura?: { serie?: string | null; folio?: string | null; uuid?: string | null };
      }>(response);
      if (!response.ok) {
        setErrorMessage(body.detail || "No se pudo emitir la factura SaaS.");
        return;
      }
      const serieFolio = `${body.factura?.serie || ""}${body.factura?.folio || ""}`.trim();
      setNotice(
        `${body.mensaje || "Factura SaaS emitida correctamente."}${
          serieFolio ? ` Folio ${serieFolio}.` : ""
        }${body.factura?.uuid ? ` UUID ${body.factura.uuid}.` : ""}`
      );
      await handleRefreshCurrentSection();
    } catch (error) {
      setErrorMessage(
        error instanceof Error ? error.message : "No se pudo emitir la factura SaaS."
      );
    } finally {
      setInvoicingSubscriptionId(null);
    }
  }

  async function handleOpenClientUsage(client: SubscriptionItem) {
    setSelectedUsageClient(client);
    setClientUsageStatement(null);
    setClientUsageError("");
    setClientUsageLoading(true);
    try {
      const payload = await fetchJson<UsageStatementPayload>(
        `/billing/admin/consumo/${client.capa_negocio.id}/estado-cuenta/`
      );
      setClientUsageStatement(payload);
    } catch (error) {
      setClientUsageError(
        error instanceof Error ? error.message : "No se pudo cargar el consumo del cliente."
      );
    } finally {
      setClientUsageLoading(false);
    }
  }

  function handleCloseClientUsage() {
    setSelectedUsageClient(null);
    setClientUsageStatement(null);
    setClientUsageError("");
  }

  async function loadClientBackups(client: SubscriptionItem) {
    setClientBackupsLoading(true);
    setClientBackupsError("");
    try {
      const payload = await fetchJson<CustomerBackupsPayload>(
        `/billing/admin/clientes/${client.capa_negocio.id}/backups/`
      );
      setClientBackups(payload.items ?? []);
    } catch (error) {
      setClientBackupsError(
        error instanceof Error
          ? error.message
          : "No se pudo cargar el historial de backups."
      );
    } finally {
      setClientBackupsLoading(false);
    }
  }

  function handleOpenClientBackups(client: SubscriptionItem) {
    setSelectedBackupClient(client);
    setClientBackups([]);
    setClientBackupsError("");
    setClientBackupReason("");
    void loadClientBackups(client);
  }

  function handleCloseClientBackups() {
    setSelectedBackupClient(null);
    setClientBackups([]);
    setClientBackupsError("");
    setClientBackupReason("");
    setClientBackupsGenerating(false);
    setRestoreCandidateBackup(null);
    setRestoreConfirmStepOne(false);
    setRestoreConfirmText("");
    setRestoreReason("");
    setRestoreValidationLoading(false);
    setRestoreInspection(null);
  }

  function clientHasVendeFacilCatalog(client: SubscriptionItem | null) {
    return effectivePlanModules(client).includes("vende_facil.productos");
  }

  function clientHasVendeFacilInventory(client: SubscriptionItem | null) {
    return effectivePlanModules(client).includes("vende_facil.inventario");
  }

  function clientHasVendeFacilOrders(client: SubscriptionItem | null) {
    return effectivePlanModules(client).includes("vende_facil.ordenes");
  }

  function handleLaunchVendeFacil(client: SubscriptionItem) {
    const platform = client.vende_facil_platform;
    if (!platform?.launch_url || !platform.ready_for_account_context) {
      setErrorMessage(
        platform?.primary_action ||
          "Sincroniza y verifica Vende Facil antes de abrir esta solucion."
      );
      return;
    }
    window.open(platform.launch_url, "_blank", "noopener,noreferrer");
  }

  async function loadVendeCatalog(
    client: SubscriptionItem,
    page = 1,
    filters?: {
      search?: string;
      categoryId?: string;
      activeFilter?: "TODOS" | "ACTIVOS" | "INACTIVOS";
    }
  ) {
    setVendeCatalogLoading(true);
    setVendeCatalogError("");
    try {
      const params = new URLSearchParams();
      const search = (filters?.search ?? vendeCatalogSearch).trim();
      const categoryId = filters?.categoryId ?? vendeCatalogCategoryId;
      const activeFilter = filters?.activeFilter ?? vendeCatalogActiveFilter;
      if (search) params.set("search", search);
      if (categoryId) params.set("categoria_id", categoryId);
      if (activeFilter === "ACTIVOS") params.set("activo", "true");
      if (activeFilter === "INACTIVOS") params.set("activo", "false");
      params.set("page", String(page));
      params.set("page_size", "20");
      const query = params.toString();
      const payload = await fetchJson<VendeFacilCatalogPayload>(
        `/vende-facil/admin/clientes/${client.capa_negocio.id}/catalogo/${query ? `?${query}` : ""}`
      );
      setVendeCatalog(payload);
      setVendeCatalogPage(payload.pagination.page);
    } catch (error) {
      setVendeCatalogError(
        error instanceof Error
          ? error.message
          : "No se pudo cargar el catalogo de Vende Facil."
      );
    } finally {
      setVendeCatalogLoading(false);
    }
  }

