  async function handleVendeOrderTransition(
    order: VendeFacilOrder,
    action: "reservar" | "confirmar" | "cancelar"
  ) {
    if (!selectedVendeOrdersClient) return;
    setVendeOrderTransitionId(order.id);
    setVendeOrdersError("");
    setNotice("");
    try {
      const payload = {
        payment_status:
          action === "confirmar"
            ? "PAGADA"
            : action === "cancelar"
              ? "CANCELADA"
              : undefined,
        nota: "Actualizado desde Backoffice BetterP.",
        restock: action === "cancelar" && order.estatus === "CONFIRMADA",
        metadata: {
          source: "betterp_backoffice",
          previous_status: order.estatus,
        },
      };
      const response = await fetch(
        buildApiUrl(
          `/vende-facil/admin/clientes/${selectedVendeOrdersClient.capa_negocio.id}/ordenes/${order.id}/${action}/`
        ),
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(payload),
        }
      );
      const body = await readJson<{ detail?: string; orden?: VendeFacilOrder }>(response);
      if (!response.ok) {
        throw new Error(body.detail || "No se pudo actualizar la orden.");
      }
      setNotice(`Orden ${body.orden?.external_order_id || order.id} actualizada.`);
      await loadVendeOrders(selectedVendeOrdersClient, vendeOrdersPage);
      await handleRefreshCurrentSection();
    } catch (error) {
      setVendeOrdersError(
        error instanceof Error ? error.message : "No se pudo actualizar la orden."
      );
    } finally {
      setVendeOrderTransitionId(null);
    }
  }

