  async function handleVendeFacilLegacyAdoption(client: SubscriptionItem, dryRun: boolean) {
    let confirmationText = "";
    if (!dryRun) {
      confirmationText =
        window.prompt(
          "Escribe ADOPT_LEGACY_DATA para asignar los datos legacy sin cuenta a este cliente.",
        )?.trim() ?? "";
      if (confirmationText !== "ADOPT_LEGACY_DATA") {
        setErrorMessage("Adopcion legacy cancelada: confirmacion requerida.");
        return;
      }
    }

    setAdoptingVendeSubscriptionId(client.id);
    setNotice("");
    setErrorMessage("");
    try {
      const response = await fetch(
        buildApiUrl(`/billing/admin/suscripciones/${client.id}/vende-facil/legacy-adoption/`),
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            dry_run: dryRun,
            confirmation_text: confirmationText,
          }),
        },
      );
      const body = await readJson<{
        detail?: string;
        mensaje?: string;
        subscription?: SubscriptionItem;
      }>(response);
      if (!response.ok || !body.subscription) {
        setErrorMessage(body.detail || "No se pudo ejecutar la adopcion legacy.");
        return;
      }
      setClients((current) =>
        current.map((item) => (item.id === body.subscription?.id ? body.subscription : item)),
      );
      setNotice(body.mensaje || "Operacion legacy de Vende Facil ejecutada.");
    } catch (error) {
      setErrorMessage(
        error instanceof Error ? error.message : "No se pudo ejecutar la adopcion legacy."
      );
    } finally {
      setAdoptingVendeSubscriptionId(null);
    }
  }

  function renderPlanChecklist({
    title,
    description,
    definitions,
    values,
    onChange,
  }: {
    title: string;
    description: string;
    definitions: PlanDefinitionItem[];
    values: string[];
    onChange: (next: string[]) => void;
  }) {
    return (
      <div className="rounded-[28px] border border-white/8 bg-zinc-950/50 p-4">
        <div className="flex flex-col gap-1">
          <p className="text-[11px] uppercase tracking-[0.22em] text-zinc-500">
            {title}
          </p>
          <p className="text-sm text-zinc-400">{description}</p>
        </div>
        <div className="mt-4 grid gap-3 md:grid-cols-2">
          {definitions.map((item) => (
            <label
              key={item.clave}
              className={`flex min-h-[84px] cursor-pointer items-start gap-3 rounded-2xl border px-4 py-3 transition ${
                values.includes(item.clave)
                  ? "border-cyan-500/25 bg-cyan-500/10"
                  : "border-white/8 bg-zinc-900/60 hover:border-white/14"
              }`}
            >
              <input
                type="checkbox"
                checked={values.includes(item.clave)}
                onChange={(event) =>
                  onChange(toggleStringValue(values, item.clave, event.target.checked))
                }
                className="mt-1 h-4 w-4 rounded border-white/10 bg-zinc-950 text-cyan-500"
              />
              <span>
                <span className="block text-sm font-semibold text-white">{item.nombre}</span>
                <span className="mt-1 block text-xs leading-5 text-zinc-500">
                  {item.descripcion}
                </span>
              </span>
            </label>
          ))}
        </div>
      </div>
    );
  }

