  async function waitForMarketingGenerationJob(jobId: number) {
    for (let attempt = 0; attempt < 180; attempt += 1) {
      const response = await fetch(buildApiUrl(`/billing/jobs/${jobId}/`), {
        cache: "no-store",
      });
      const body = await readJson<BackgroundJobStatus | { detail?: string }>(response);
      if (!response.ok) {
        throw new Error(
          (body as { detail?: string }).detail ||
            "No se pudo consultar el avance de la generacion editorial."
        );
      }
      const job = body as BackgroundJobStatus;
      if (job.status === "SUCCESS" && job.result) {
        return job.result;
      }
      if (job.status === "ERROR" || job.status === "CANCELLED") {
        throw new Error(job.error || "La generacion editorial termino con error.");
      }
      setMarketingQueueGenerationPhase(
        job.status === "RUNNING"
          ? "GPT-5.5 esta generando las piezas en segundo plano..."
          : "Generacion en cola; esperando proceso en segundo plano..."
      );
      await sleep(2000);
    }
    throw new Error("La generacion sigue en proceso. Revisa salud operativa en unos minutos.");
  }

