  async function handleMarketingSocialInteractionStatus(
    interactionId: number,
    estatus: MarketingSocialInteractionItem["estatus"]
  ) {
    setNotice("");
    setErrorMessage("");
    const response = await fetch(
      buildApiUrl(`/billing/admin/marketing/social-inbox/${interactionId}/`),
      {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ estatus }),
      }
    );
    const body = await readJson<{
      detail?: string;
      mensaje?: string;
      interaction?: MarketingSocialInteractionItem;
    }>(response);
    if (!response.ok || !body.interaction) {
      setErrorMessage(body.detail || "No se pudo actualizar la interaccion social.");
      return;
    }
    setMarketing((current) => {
      if (!current?.social_inbox) return current;
      const items = current.social_inbox.items.map((item) =>
        item.id === interactionId ? body.interaction! : item
      );
      const pending = items.filter((item) => item.estatus === "PENDING").length;
      return {
        ...current,
        social_inbox: {
          ...current.social_inbox,
          items,
          summary: { ...current.social_inbox.summary, pending },
        },
      };
    });
    setNotice(body.mensaje || "Interaccion actualizada.");
  }

  function toggleCampaignChannel(channel: SocialChannelItem) {
    setCampaignDraft((current) => {
      const exists = current.canales_ids.includes(channel.id);
      return {
        ...current,
        canales_ids: exists
          ? current.canales_ids.filter((item) => item !== channel.id)
          : [...current.canales_ids, channel.id],
        ...(channel.red === "TIKTOK"
          ? {
              tiktok_consent_confirmed: false,
              ...(exists ? { tiktok_privacy_level: "" } : {}),
            }
          : {}),
      };
    });
    if (channel.red === "TIKTOK" && !campaignDraft.canales_ids.includes(channel.id)) {
      void loadTikTokCreatorInfo(channel.id);
    }
  }

  async function handleCreateCampaign(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setNotice("");
    setErrorMessage("");
    const scheduledAt = campaignDraft.programada_en.trim();
    const selectedTikTok = (marketing?.redes ?? []).some(
      (channel) =>
        channel.red === "TIKTOK" && campaignDraft.canales_ids.includes(channel.id)
    );
    if (
      selectedTikTok &&
      campaignDraft.tiktok_publish_mode === "DIRECT_POST" &&
      !campaignDraft.tiktok_privacy_level
    ) {
      setErrorMessage("Selecciona la privacidad de TikTok antes de continuar.");
      return;
    }
    if (selectedTikTok && !campaignDraft.tiktok_consent_confirmed) {
      setErrorMessage("Confirma que revisaste y autorizas el envío del contenido a TikTok.");
      return;
    }
    if (scheduledAt) {
      const scheduledDate = new Date(scheduledAt);
      if (
        Number.isNaN(scheduledDate.getTime()) ||
        scheduledDate.getTime() <= Date.now() + 10 * 60 * 1000
      ) {
        setErrorMessage("Programa la campaña con al menos 10 minutos de anticipación.");
        return;
      }
    }
    const response = await fetch(buildApiUrl("/billing/admin/campanas/"), {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        ...campaignDraft,
        programada_en: scheduledAt || null,
      }),
    });
    const body = await readJson<{ detail?: string; mensaje?: string }>(response);
    if (!response.ok) {
      setErrorMessage(body.detail || "No se pudo crear la campaña.");
      return;
    }
    setNotice(body.mensaje || "Campaña creada correctamente.");
    setCampaignDraft(createCampaignDraft());
    await loadSection("marketing", true);
  }

  async function handleGenerateMarketingQueue() {
    if (isGeneratingMarketingQueue) return;
    const approvedWeeklyPlan =
      marketing?.weekly_plan?.status === "APPROVED" ? marketing.weekly_plan : null;
    if (approvedWeeklyPlan) {
      await handleGenerateMarketingWeeklyPlan(approvedWeeklyPlan);
      return;
    }
    setNotice("");
    setErrorMessage("");
    setSelectedMarketingCampaign(null);
    setSelectedMarketingCampaignIds([]);
    setMarketingCampaignBusyAction("generate-queue");
    setMarketingQueueGenerationPhase("Preparando aprendizaje y cola activa...");
    setIsGeneratingMarketingQueue(true);
    const useLearningPlan = Boolean(marketing?.learning?.next_experiments?.length);
    try {
      setMarketingQueueGenerationPhase(
        useLearningPlan
          ? "Creando 7 posts con aprendizaje, una solicitud IA por pieza..."
          : "Creando 7 posts base, una solicitud IA por pieza..."
      );
      const response = await fetch(
        buildApiUrl("/billing/admin/marketing/content-engine/generate-week/?async_job=true"),
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            days: 7,
            local_time: "10:15",
            use_learning: useLearningPlan,
            learning_window_days: marketing?.learning?.window_days ?? 30,
          }),
        }
      );
      const body = await readJson<{
        detail?: string;
        mensaje?: string;
        accepted?: boolean;
        job_id?: number;
      }>(response);
      if (!response.ok) {
        setErrorMessage(body.detail || "No se pudo generar la cola editorial.");
        return;
      }
      const result =
        body.accepted && body.job_id
          ? await waitForMarketingGenerationJob(body.job_id)
          : ({ mensaje: body.mensaje } satisfies MarketingGenerationJobResult);
      setNotice(result.mensaje || body.mensaje || "Cola editorial generada correctamente.");
      setMarketingQueueGenerationPhase("Actualizando tabla y banderas de modelo...");
      await loadSection("marketing", true);
    } catch (error) {
      setErrorMessage(
        error instanceof Error
          ? `No se pudo generar la cola editorial: ${error.message}`
          : "No se pudo generar la cola editorial por un error de red."
      );
    } finally {
      setIsGeneratingMarketingQueue(false);
      setMarketingQueueGenerationPhase("");
      setMarketingCampaignBusyAction("");
    }
  }

