  async function handleMarketingWeeklyPlanItemDecision(
    plan: MarketingWeeklyPlan,
    experiment: MarketingLearningExperiment,
    decision: "APPROVE" | "REJECT" | "REPLACE"
  ) {
    let replacement: Record<string, string> = {};
    if (decision === "REPLACE") {
      const title = window.prompt(
        "Nuevo titulo para esta pieza:",
        experiment.title || ""
      );
      if (title === null) return;
      const creativeFormat = window.prompt(
        "Nuevo formato creativo:",
        experiment.creative_format || ""
      );
      if (creativeFormat === null) return;
      const hook = window.prompt(
        "Nuevo hook para esta pieza:",
        experiment.recommended_hook || ""
      );
      if (hook === null) return;
      const cta = window.prompt(
        "Nuevo CTA para esta pieza:",
        experiment.recommended_cta || experiment.cta || ""
      );
      if (cta === null) return;
      const hypothesis = window.prompt(
        "Nueva hipotesis que quieres probar:",
        experiment.hypothesis || ""
      );
      if (hypothesis === null) return;
      const candidates = {
        title: title.trim(),
        creative_format: creativeFormat.trim(),
        recommended_hook: hook.trim(),
        recommended_cta: cta.trim(),
        hypothesis: hypothesis.trim(),
      };
      const originals: Record<keyof typeof candidates, string> = {
        title: experiment.title || "",
        creative_format: experiment.creative_format || "",
        recommended_hook: experiment.recommended_hook || "",
        recommended_cta: experiment.recommended_cta || experiment.cta || "",
        hypothesis: experiment.hypothesis || "",
      };
      replacement = Object.fromEntries(
        Object.entries(candidates).filter(
          ([key, value]) => value && value !== originals[key as keyof typeof candidates].trim()
        )
      );
      if (!Object.keys(replacement).length) {
        setErrorMessage("Cambia al menos el titulo, formato, hook, CTA o hipotesis.");
        return;
      }
    }
    const busyKey = `weekly-plan-${plan.id}-${experiment.day}-${decision.toLowerCase()}`;
    setNotice("");
    setErrorMessage("");
    setMarketingCampaignBusyAction(busyKey);
    try {
      const response = await fetch(
        buildApiUrl(`/billing/admin/marketing/weekly-plan/${plan.id}/item/`),
        {
          method: "PATCH",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            day: experiment.day,
            decision,
            replacement,
            notes: decision === "REPLACE" ? "Ajuste solicitado por el owner." : "",
          }),
        }
      );
      const body = await readJson<{
        detail?: string;
        mensaje?: string;
        weekly_plan?: MarketingWeeklyPlan;
      }>(response);
      if (!response.ok || !body.weekly_plan) {
        setErrorMessage(body.detail || "No se pudo guardar la decision de la pieza.");
        return;
      }
      updateMarketingWeeklyPlanState(body.weekly_plan);
      setNotice(body.mensaje || "Decision semanal guardada.");
    } finally {
      setMarketingCampaignBusyAction("");
    }
  }

