  async function handleRegenerateMarketingCampaign(campaignId: number) {
    if (!marketingCampaignFeedback.trim()) {
      setErrorMessage("Agrega comentarios concretos para regenerar la campaña.");
      return;
    }
    setMarketingCampaignBusyAction(`regenerate-${campaignId}`);
    setNotice("");
    setErrorMessage("");
    try {
      const response = await fetch(
        buildApiUrl(`/billing/admin/campanas/${campaignId}/regenerar/`),
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ feedback: marketingCampaignFeedback }),
        }
      );
      const body = await readJson<{
        detail?: string;
        mensaje?: string;
        campana?: MarketingCampaignItem;
      }>(response);
      if (!response.ok || !body.campana) {
        setErrorMessage(body.detail || "No se pudo regenerar la campaña.");
        return;
      }
      updateMarketingCampaignState(body.campana);
      setSelectedMarketingAssetIds([]);
      let refreshedCampaign: MarketingCampaignItem | null = null;
      try {
        refreshedCampaign = await refreshMarketingCampaignFromServer(campaignId);
      } catch (refreshError) {
        setErrorMessage(
          refreshError instanceof Error
            ? refreshError.message
            : "La campaña se regeneró, pero no pudimos refrescar la tabla."
        );
      }
      setNotice(
        refreshedCampaign
          ? body.mensaje || "Campaña regenerada."
          : "Campaña regenerada. Actualiza marketing si no ves el cambio en la tabla."
      );
    } finally {
      setMarketingCampaignBusyAction("");
    }
  }

  async function handleSaveDestinationMetrics(
    campaignId: number,
    destinationId: number,
    options: { refreshMarketing?: boolean } = {}
  ) {
    const draft =
      campaignDestinationMetricDrafts[destinationId] ?? createDestinationMetricDraft();
    const toNumber = (value: string) => {
      const parsed = Number(value || 0);
      return Number.isFinite(parsed) && parsed > 0 ? parsed : 0;
    };
    setMarketingCampaignBusyAction(`metrics-${destinationId}`);
    setNotice("");
    setErrorMessage("");
    try {
      const response = await fetch(
        buildApiUrl(`/billing/admin/campanas/${campaignId}/destinos/${destinationId}/metricas/`),
        {
          method: "PATCH",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            impressions: Math.round(toNumber(draft.impressions)),
            clicks: Math.round(toNumber(draft.clicks)),
            engagement: Math.round(toNumber(draft.engagement)),
            leads: Math.round(toNumber(draft.leads)),
            spend: toNumber(draft.spend),
            traffic_type: draft.traffic_type,
            period_start: draft.period_start,
            period_end: draft.period_end,
            notes: draft.notes,
          }),
        }
      );
      const body = await readJson<{
        detail?: string;
        mensaje?: string;
        campana?: MarketingCampaignItem;
      }>(response);
      if (!response.ok || !body.campana) {
        setErrorMessage(body.detail || "No se pudieron actualizar las métricas.");
        return;
      }
      updateMarketingCampaignState(body.campana);
      syncDestinationMetricDrafts(body.campana);
      setNotice(body.mensaje || "Metricas actualizadas.");
      if (options.refreshMarketing) {
        await loadSection("marketing", true);
      }
    } finally {
      setMarketingCampaignBusyAction("");
    }
  }

