  async function handleUploadCampaignAsset(campaignId: number) {
    const draft = campaignAssetDrafts[campaignId];
    if (!draft?.file) {
      setErrorMessage("Selecciona una imagen o video antes de cargar el creativo.");
      return;
    }

    setMarketingCampaignBusyAction(`upload-asset-${campaignId}`);
    setNotice("");
    setErrorMessage("");
    try {
      const formData = new FormData();
      formData.append("file", draft.file);
      if (draft.titulo.trim()) {
        formData.append("titulo", draft.titulo.trim());
      }

      const response = await fetch(
        buildApiUrl(`/billing/admin/campanas/${campaignId}/activos/`),
        {
          method: "POST",
          body: formData,
        }
      );
      const body = await readJson<{
        detail?: string;
        mensaje?: string;
        activo?: MarketingCampaignAssetItem;
      }>(response);
      if (!response.ok || !body.activo) {
        setErrorMessage(body.detail || "No se pudo cargar el creativo.");
        return;
      }
      appendMarketingCampaignAsset(campaignId, body.activo);
      resetCampaignAssetDraft(campaignId);
      setNotice(body.mensaje || "Creativo cargado correctamente.");
    } finally {
      setMarketingCampaignBusyAction("");
    }
  }

  async function launchMarketingCampaignRequest(campaignId: number) {
    const response = await fetch(
      buildApiUrl(`/billing/admin/campanas/${campaignId}/disparar/`),
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ notas_internas: "" }),
      }
    );
    const body = await readJson<{ detail?: string; mensaje?: string }>(response);
    return { response, body };
  }

  async function handleLaunchCampaign(campaignId: number) {
    const campaign = (marketing?.campanas ?? []).find((item) => item.id === campaignId);
    if (campaign?.estatus === "PUBLICADA") {
      setErrorMessage("Esta campaña ya fue publicada.");
      return;
    }
    const confirmed = window.confirm(
      "Esto publicará esta campaña ahora en sus destinos configurados. Continuar?"
    );
    if (!confirmed) return;

    setMarketingCampaignBusyAction(`launch-${campaignId}`);
    setNotice("");
    setErrorMessage("");
    try {
      const { response, body } = await launchMarketingCampaignRequest(campaignId);
      if (!response.ok) {
        setErrorMessage(body.detail || "No se pudo disparar la campaña.");
        return;
      }
      setNotice(body.mensaje || "Campaña disparada correctamente.");
      await loadSection("marketing", true);
    } finally {
      setMarketingCampaignBusyAction("");
    }
  }

  async function handleLaunchSelectedMarketingCampaigns(ids: number[]) {
    const selectedIds = Array.from(new Set(ids)).filter(Boolean);
    const launchableIds = selectedIds.filter((id) => {
      const campaign = (marketing?.campanas ?? []).find((item) => item.id === id);
      return campaign && campaign.estatus !== "PUBLICADA";
    });
    if (!launchableIds.length) {
      setErrorMessage("Selecciona al menos una campaña pendiente para publicar ahora.");
      return;
    }
    const confirmed = window.confirm(
      launchableIds.length === 1
        ? "Esto publicará ahora la campaña seleccionada. Continuar?"
        : `Esto publicará ahora ${launchableIds.length} campañas seleccionadas. Continuar?`
    );
    if (!confirmed) return;

    setMarketingCampaignBusyAction(`launch-${launchableIds.join("-")}`);
    setNotice("");
    setErrorMessage("");
    const errors: string[] = [];
    let launched = 0;
    try {
      for (const campaignId of launchableIds) {
        const { response, body } = await launchMarketingCampaignRequest(campaignId);
        if (!response.ok) {
          errors.push(body.detail || `No se pudo disparar campaña ${campaignId}.`);
          continue;
        }
        launched += 1;
      }
      setSelectedMarketingCampaignIds((current) =>
        current.filter((item) => !launchableIds.includes(item))
      );
      if (launched) {
        setNotice(`${formatNumber(launched)} campaña(s) enviadas ahora.`);
      }
      if (errors.length) {
        setErrorMessage(errors.join(" "));
      }
      await loadSection("marketing", true);
    } finally {
      setMarketingCampaignBusyAction("");
    }
  }

