  async function handleMarkMarketingProspectLost(prospect: ProspectItem) {
    const lostReason = window.prompt(
      "Objecion principal para marcar perdido. Ej: precio, falta de tiempo, no encaja, migracion, confianza."
    );
    if (lostReason === null) return;
    const cleanLostReason = lostReason.trim();
    if (!cleanLostReason) {
      setErrorMessage("Captura la objecion principal antes de marcar el prospecto como perdido.");
      setNotice("");
      return;
    }
    setMarketingProspectBusyAction(`lost-${prospect.id}`);
    setNotice("");
    setErrorMessage("");
    const lostNote = marketingProspectLostNote(prospect, cleanLostReason);
    const nextNotes = [prospect.notas_internas?.trim(), lostNote]
      .filter(Boolean)
      .join("\n");
    try {
      const response = await fetch(buildApiUrl(`/billing/admin/prospectos/${prospect.id}/`), {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          etapa: "PERDIDO",
          notas_internas: nextNotes,
          solution_key: prospect.solution_key || prospect.requested_solution_key || "renta_facil",
          lost_reason: cleanLostReason,
          commercial_objection: cleanLostReason,
        }),
      });
      const body = await readJson<{ detail?: string }>(response);
      if (!response.ok) {
        setErrorMessage(body.detail || "No se pudo marcar el prospecto como perdido.");
        return;
      }
      setNotice("Prospecto marcado como perdido con objecion registrada.");
      await loadSection("marketing", true);
    } finally {
      setMarketingProspectBusyAction("");
    }
  }

  async function handleRevokePlatformInvitation(invitationId: number) {
    if (!window.confirm("¿Seguro que quieres revocar esta invitación pendiente?")) {
      return;
    }
    setNotice("");
    setErrorMessage("");
    const response = await fetch(
      buildApiUrl(`/accounts/platform-admins/invitaciones/${invitationId}/`),
      { method: "DELETE" }
    );
    const body = await readJson<{ detail?: string; mensaje?: string }>(response);
    if (!response.ok) {
      setErrorMessage(body.detail || "No se pudo revocar la invitación.");
      return;
    }
    setNotice(body.mensaje || "Invitación revocada.");
    await loadSection("admins", true);
  }

